'use strict';
/* ARCHI-SPACE v1. Content is bilingual; proposed activities are not claimed as results. */
const STORE='archispace-v1';
let state={lang:'en',notes:{},checks:{}};
try{Object.assign(state,JSON.parse(localStorage.getItem(STORE)||'{}'));}catch{}
if(!['en','bm'].includes(state.lang))state.lang='en';
state.notes=state.notes||{};state.checks=state.checks||{};
let stage=0,filter='all';
const t=(en,bm)=>state.lang==='bm'?bm:en;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const save=()=>{try{localStorage.setItem(STORE,JSON.stringify(state));return true;}catch{return false;}};
const svg=(type='arrow')=>{const paths={arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',cube:'<path d="m12 3 9 5v9l-9 5-9-5V8l9-5Zm0 10v9M3 8l9 5 9-5"/>',eye:'<path d="M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12Z"/><circle cx="12" cy="12" r="3"/>',layers:'<path d="m12 3 10 5-10 5L2 8l10-5Zm-10 9 10 5 10-5M2 16l10 5 10-5"/>',check:'<path d="m5 12 4 4L19 6M20 13v7H4V4h10"/>',book:'<path d="M12 5v16M3 3l9 2 9-2v16l-9 2-9-2V3Z"/>'};return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[type]||paths.arrow}</svg>`;};
const icon=x=>`<div class="icon">${svg(x)}</div>`;
const button=(href,en,bm,primary=false)=>`<a class="button ${primary?'primary':''}" href="${href}">${t(en,bm)} ${svg()}</a>`;
const badge=(en,bm,type='')=>`<span class="pill ${type}">${t(en,bm)}</span>`;
const pageHero=(num,kicker,title,btitle,desc,bdesc,file,en,bm,captionEn,captionBm,ctaHref,ctaEn,ctaBm,cta2Href,cta2En,cta2Bm)=>`<section class="hero page-hero"><img src="assets/heroes/${file}.png" alt="${t(en,bm)}" loading="lazy"><div class="hero-copy"><div class="eyebrow"><span class="dot"></span>${num} / ${kicker}</div><h1>${t(title,btitle)}</h1><p>${t(desc,bdesc)}</p><div class="actions">${button(ctaHref,ctaEn,ctaBm,true)}${button(cta2Href,cta2En,cta2Bm)}</div></div><span class="hero-note">${t(captionEn,captionBm)}</span></section>`;

const pages=[['overview','Why develop it?','Mengapa dibangunkan?'],['why','The starting point','Titik permulaan'],['evidence','ARCHI-KIT evidence','Bukti ARCHI-KIT'],['sustain','The evolution','Perkembangan'],['model','How it works','Cara ia berfungsi'],['challenge','Implementation & impact','Pelaksanaan & impak'],['resources','What comes next','Langkah seterusnya']];
const stages=[
 {letter:'S',name:'Sense',bm:'Alami & perhatikan',en:'Experience the parts. Notice the space.',desc:'Observe the ARCHI-KIT components and explore the initial digital space. Record what you notice before making judgements.',bdesc:'Perhatikan komponen ARCHI-KIT dan teroka ruang digital awal. Catat pemerhatian sebelum membuat penilaian.',steps:['Inspect a physical component and its AR representation.','Identify its position in the building model.','Record two observations about scale or assembly.'],bstep:['Periksa komponen fizikal dan paparan AR.','Kenal pasti kedudukannya dalam model bangunan.','Catat dua pemerhatian tentang skala atau pemasangan.'],output:'Annotated observations and a component photograph.',boutput:'Catatan beranotasi dan foto komponen.'},
 {letter:'P',name:'Perceive',bm:'Fahami hubungan',en:'Connect drawings, components and space.',desc:'Interpret the relationships you observed. Compare a drawing with the physical and digital models.',bdesc:'Tafsir hubungan yang diperhatikan. Bandingkan lukisan dengan model fizikal dan digital.',steps:['Match a component to its plan or section.','Explain one relationship between structure and space.','Describe the difference between model scale and user experience.'],bstep:['Padankan komponen dengan pelan atau keratan.','Terangkan satu hubungan antara struktur dengan ruang.','Jelaskan perbezaan skala model dengan pengalaman pengguna.'],output:'A drawing–model comparison with explanations.',boutput:'Perbandingan lukisan dan model berserta penerangan.'},
 {letter:'A',name:'Analyse',bm:'Analisis pilihan',en:'Ask better questions of the design.',desc:'Compare alternatives against a client brief. Separate visual impressions from claims requiring technical verification.',bdesc:'Bandingkan pilihan berdasarkan brief klien. Bezakan tanggapan visual dengan dakwaan yang memerlukan pengesahan teknikal.',steps:['Compare privacy, views and spatial arrangement.','Identify one inconsistency or design concern.','Flag any claim about energy, structure or comfort that needs verification.'],bstep:['Bandingkan privasi, pandangan dan susun atur ruang.','Kenal pasti satu ketidakselarasan atau isu reka bentuk.','Tandakan dakwaan tenaga, struktur atau keselesaan yang perlu disahkan.'],output:'An issue log and a justified option comparison.',boutput:'Log isu dan perbandingan pilihan berserta alasan.'},
 {letter:'C',name:'Create',bm:'Hasilkan & pinda',en:'Turn a decision into a design revision.',desc:'Develop the selected solution in the actual model. An AI-generated concept image is not a verified construction model.',bdesc:'Kembangkan penyelesaian dalam model sebenar. Imej konsep janaan AI bukan model pembinaan yang telah disahkan.',steps:['Choose one revision and explain its purpose.','Update the digital model and corresponding drawing.','Create an AR asset where supported by the course and available tools.'],bstep:['Pilih satu pindaan dan jelaskan tujuannya.','Kemas kini model digital dan lukisan berkaitan.','Hasilkan aset AR mengikut kursus dan kemudahan yang tersedia.'],output:'A revised model, drawing and change log.',boutput:'Model, lukisan dan log perubahan yang dikemas kini.'},
 {letter:'E',name:'Evaluate',bm:'Nilai & tambah baik',en:'Review. Explain. Improve again.',desc:'Test the revision through client or peer review. Return to an earlier stage if the problem remains unresolved.',bdesc:'Semak pindaan bersama klien atau rakan. Kembali ke peringkat terdahulu jika masalah belum diselesaikan.',steps:['Demonstrate the revised model and tool operation.','Collect specific feedback against the brief.','Record what improved and what still needs work.'],bstep:['Demonstrasikan model yang dipinda dan penggunaan alat.','Dapatkan maklum balas khusus berdasarkan brief.','Catat penambahbaikan dan perkara yang masih perlu diusahakan.'],output:'Before–after evidence, feedback and individual reflection.',boutput:'Bukti sebelum–selepas, maklum balas dan refleksi individu.'}
];
function overview(){return `<section class="hero connected-hero"><img src="assets/hero-page-01.png" alt="${t('Conceptual physical model, digital wireframe and VR learner','Ilustrasi konsep model fizikal, rangka digital dan pengguna VR')}"><div class="hero-copy"><div class="eyebrow">${t('FROM ARCHI-KIT TO ARCHI-SPACE','DARIPADA ARCHI-KIT KEPADA ARCHI-SPACE')}</div><h1>${t('You can build the model.<br><span class="gradient">But can you experience the space?</span>','Anda boleh membina model.<br><span class="gradient">Tetapi, bagaimana rasanya berada di dalam ruang itu?</span>')}</h1><p>${t('Understanding how construction components connect is one part of architectural learning. Understanding how people experience the spaces they create is another. ARCHI-SPACE connects these learning needs through a physical–digital journey, building on the ARCHI-KIT foundation within Immersive XR.','Memahami bagaimana komponen binaan bersambung ialah satu aspek pembelajaran seni bina. Memahami pengalaman pengguna dalam ruang yang direka ialah satu lagi. ARCHI-SPACE menghubungkan kedua-duanya melalui pembelajaran fizikal–digital, berasaskan pengalaman ARCHI-KIT dalam konteks Immersive XR.')}</p><div class="actions">${button('#why','Explore the ARCHI-KIT foundation','Kenali asas ARCHI-KIT',true)}${button('#sustain','See the development journey','Lihat perjalanan pembangunan')}</div></div><span class="hero-note">${t('AI conceptual illustration · not implementation evidence','Ilustrasi konsep AI · bukan bukti pelaksanaan')}</span></section>
<section class="connected-journey"><div class="eyebrow">${t('THREE CONNECTED LEARNING QUESTIONS','TIGA PERSOALAN PEMBELAJARAN YANG SALING BERKAITAN')}</div><div class="section-head"><h2>${t('From understanding construction<br>to experiencing architecture.','Daripada memahami binaan<br>kepada mengalami ruang seni bina.')}</h2></div><div class="continuity-cards">
<article class="continuity-card foundation"><span class="continuity-number">01</span><h3>${t('Understand the connection','Fahami sambungan')}</h3><p>${t('How can a 2D drawing be interpreted as a three-dimensional joint or component?','Bagaimana lukisan 2D diterjemahkan kepada sambungan dan komponen 3D?')}</p><p class="learning-focus">ARCHI-KIT · ${t('Physical 3D + interactive AR','Model fizikal 3D + AR interaktif')}</p></article>
<article class="continuity-card question"><span class="continuity-number">02</span><h3>${t('Experience the space','Alami ruang')}</h3><p>${t('How can layout, scale and movement be explored from the user’s perspective?','Bagaimana susun atur, skala dan pergerakan diteroka daripada perspektif pengguna?')}</p><p class="learning-focus">ARCHI-SPACE · ${t('Spatial exploration','Penerokaan ruang')}</p></article>
<article class="continuity-card continuation"><span class="continuity-number">03</span><h3>${t('Explain the decision','Jelaskan keputusan')}</h3><p>${t('What issue was identified—and why was a particular design revision made?','Apakah isu yang dikenal pasti, dan mengapa sesuatu pindaan dibuat?')}</p><p class="learning-focus">SPACE · ${t('Observation, review and reflection','Pemerhatian, semakan dan refleksi')}</p></article></div>
<p class="continuity-summary">${t('<strong>ARCHI-KIT</strong> provides the physical–AR foundation. <strong>ARCHI-SPACE</strong> extends the spatial learning experience. <strong>SPACE</strong> guides learner actions.','<strong>ARCHI-KIT</strong> menyediakan asas fizikal–AR. <strong>ARCHI-SPACE</strong> memperluas pengalaman pembelajaran ruang. <strong>SPACE</strong> memandu tindakan pelajar.')}</p></section>
<section class="curriculum-banner"><div class="eyebrow">CDIO × SPACE</div><h2>${t('One studio design. More ways to learn.','Satu reka bentuk studio. Pelbagai pengalaman pembelajaran.')}</h2><p>${t('The DCA40462 project reuses a DCA30364 Design Studio 3 model for VR/AR development. Explore the curriculum connection in How it works.','Projek DCA40462 menggunakan semula model DCA30364 Design Studio 3 untuk pembangunan VR/AR. Teroka hubungan kurikulum dalam Cara ia berfungsi.')}</p>${button('#model','Explore CDIO + SPACE','Teroka CDIO + SPACE',true)}</section>
${bridge('Start with the physical–AR system that connects drawings and timber components.','Mulakan dengan sistem fizikal–AR yang menghubungkan lukisan dan komponen kayu.','#why')}`;}
function why(){return pageHero('02',t('THE ARCHI-KIT FOUNDATION','ASAS ARCHI-KIT'),'Understand the joint.<br>Connect the drawing to the model.','Fahami sambungan.<br>Hubungkan lukisan dengan model.','ARCHI-KIT combines physical 3D prototypes with interactive augmented reality to support timber construction learning. Students move between drawings, tangible components and digital representations to examine how structural parts connect.','ARCHI-KIT menggabungkan prototaip fizikal 3D dengan realiti terimbuh interaktif untuk menyokong pembelajaran pembinaan kayu. Pelajar menggunakan lukisan, komponen fizikal dan perwakilan digital untuk meneliti bagaimana bahagian struktur bersambung.','hero-page-02','Abstract bridge from physical model to immersive architectural space','Jambatan abstrak daripada model fizikal kepada pengalaman ruang imersif','General ARCHI-SPACE hero · bridge from tangible learning into spatial experience.','Hero umum ARCHI-SPACE · jambatan daripada pembelajaran maujud kepada pengalaman ruang.','#evidence','See what students reported','Lihat maklum balas pelajar','#model','See the curriculum link','Lihat hubungan kurikulum')+`
<section class="curriculum-banner"><div class="eyebrow">${t('PHYSICAL 3D + INTERACTIVE AR','MODEL FIZIKAL 3D + AR INTERAKTIF')}</div><h2>${t('Make abstract drawings tangible—and interactive.','Jadikan lukisan abstrak lebih nyata dan interaktif.')}</h2><p>${t('Students connect drawings with structural components they can handle and digital representations they can explore. The physical model and AR content work together as one learning system, rather than two unrelated resources.','Pelajar menghubungkan lukisan dengan komponen struktur yang boleh dipegang serta perwakilan digital yang boleh diteroka. Model fizikal dan kandungan AR berfungsi bersama sebagai satu sistem pembelajaran, bukan dua sumber yang terpisah.')}</p></section>
<div class="section-head"><h2>${t('ARCHI-KIT evidence: product, AR and classroom use.','Bukti ARCHI-KIT: produk, AR dan penggunaan di kelas.')}</h2></div>
<div class="evidence-media-grid">
<figure class="media-proof"><img src="assets/archi-kit-product.png" alt="${t('ARCHI-KIT product set showing physical prototypes and AR integration on a tablet','Set produk ARCHI-KIT yang menunjukkan prototaip fizikal dan integrasi AR pada tablet')}"><figcaption>${t('<strong>Product evidence.</strong> The ARCHI-KIT learning ecosystem combines physical prototypes with AR integration.','<strong>Bukti produk.</strong> Ekosistem pembelajaran ARCHI-KIT menggabungkan prototaip fizikal dengan integrasi AR.')}</figcaption></figure>
<figure class="media-proof"><img src="assets/archi-kit-classroom.png" alt="${t('Students collaboratively using ARCHI-KIT physical models and AR components','Pelajar menggunakan model fizikal dan komponen AR ARCHI-KIT secara kolaboratif')}"><figcaption>${t('<strong>Classroom evidence.</strong> Students use the physical kit and AR components collaboratively during learning activities.','<strong>Bukti penggunaan kelas.</strong> Pelajar menggunakan kit fizikal dan komponen AR secara kolaboratif semasa aktiviti pembelajaran.')}</figcaption></figure>
</div>
<section class="video-preview-card">
<div><span class="label">${t('ARCHI-KIT VIDEO EVIDENCE','BUKTI VIDEO ARCHI-KIT')}</span><h2>${t('Watch short product and usage previews.','Tonton pratonton ringkas produk dan cara penggunaannya.')}</h2><p>${t('These short web-preview clips support the ARCHI-KIT narrative with real product and usage evidence: the physical kit, marker access, AR interaction and student learning sequence. Full-length videos should be stored in the evidence repository or YouTube for panel review.','Klip pratonton web yang ringkas ini menyokong naratif ARCHI-KIT dengan bukti produk dan penggunaan sebenar: kit fizikal, akses penanda, interaksi AR dan urutan pembelajaran pelajar. Video penuh wajar disimpan dalam repositori bukti atau YouTube untuk semakan panel.')}</p></div>
<ol class="preview-steps">
<li><strong>${t('Show the kit','Tunjukkan kit')}</strong><span>${t('Physical timber construction prototype and printed marker/QR access.','Prototaip pembinaan kayu fizikal dan penanda/akses QR bercetak.')}</span></li>
<li><strong>${t('Scan the marker','Imbas penanda')}</strong><span>${t('Phone, tablet or laptop camera connects the physical object to AR content.','Kamera telefon, tablet atau komputer riba menghubungkan objek fizikal kepada kandungan AR.')}</span></li>
<li><strong>${t('View AR assembly','Lihat pemasangan AR')}</strong><span>${t('Digital overlay shows component position, exploded view or assembly sequence where supported.','Paparan digital menunjukkan kedudukan komponen, exploded view atau urutan pemasangan jika disokong.')}</span></li>
<li><strong>${t('Explain the joint','Terangkan sambungan')}</strong><span>${t('Student compares the physical model, AR view and working drawing.','Pelajar membandingkan model fizikal, paparan AR dan lukisan kerja.')}</span></li>
</ol>
</section>
<div class="video-evidence-grid">
<article class="video-proof-card"><video controls preload="metadata" poster="assets/archi-kit-product.png" aria-label="ARCHI-KIT product video preview"><source src="assets/video/archi-kit-product-demo.mp4" type="video/mp4">${t('Video unavailable.','Video tidak tersedia.')}</video><div><span class="label">${t('VIDEO 01 · PRODUCT PREVIEW','VIDEO 01 · PRATONTON PRODUK')}</span><h3>Video Product_ARCHI KIT</h3><p>${t('Short preview showing the ARCHI-KIT product ecosystem and how the physical learning kit is presented as an AR-supported resource.','Pratonton ringkas yang menunjukkan ekosistem produk ARCHI-KIT dan cara kit pembelajaran fizikal dipersembahkan sebagai sumber yang disokong AR.')}</p></div></article>
<article class="video-proof-card"><video controls preload="metadata" poster="assets/archi-kit-classroom.png" aria-label="How to use ARCHI-KIT video preview"><source src="assets/video/archi-kit-how-to-use.mp4" type="video/mp4">${t('Video unavailable.','Video tidak tersedia.')}</video><div><span class="label">${t('VIDEO 02 · USAGE PREVIEW','VIDEO 02 · PRATONTON PENGGUNAAN')}</span><h3>How to use ARCHI-KIT</h3><p>${t('Short preview demonstrating the usage flow so evaluators can understand the bridge between the physical prototype, AR content and student explanation.','Pratonton ringkas yang menunjukkan aliran penggunaan supaya penilai dapat memahami hubungan antara prototaip fizikal, kandungan AR dan penerangan pelajar.')}</p></div></article>
</div>
${archiKitOutcomeGallery()}<div class="section-head"><h2>${t('How students use ARCHI-KIT.','Cara pelajar menggunakan ARCHI-KIT.')}</h2></div><div class="grid2 phase-a-steps">
${storyCard('01','Handle the physical prototype','Kendalikan prototaip fizikal','Inspect and rotate a timber-joint model. Relate its components to the corresponding drawing and explore how the parts fit together.','Teliti dan putar model sambungan kayu. Padankan komponennya dengan lukisan berkaitan dan teroka cara bahagian tersebut bercantum.','tint')}
${storyCard('02','Scan to access the AR content','Imbas untuk mengakses kandungan AR','Use a compatible camera-enabled device to scan the kit’s marker or access code. The linked AR experience connects the physical resource with the digital model.','Gunakan peranti berkamera yang serasi untuk mengimbas penanda atau kod akses kit. Pengalaman AR yang dipautkan menghubungkan sumber fizikal dengan model digital.')}
${storyCard('03','Explore the digital representation','Teroka perwakilan digital','View the interactive overlay and available assembly animations. Rotate or zoom where supported to inspect connections and the relationship between parts.','Lihat paparan interaktif dan animasi pemasangan yang tersedia. Putar atau zum jika disokong untuk meneliti sambungan dan hubungan antara komponen.')}
${storyCard('04','Compare, assemble and explain','Bandingkan, pasang dan terangkan','Move between the physical model, AR view and drawing. Explain how the joint fits together and revisit the representation when a connection is unclear.','Gunakan model fizikal, paparan AR dan lukisan secara bergilir. Terangkan cara sambungan dipasang dan semak semula paparan apabila sesuatu hubungan belum jelas.','tint')}
</div><p class="source-note spacer">${t('The TSJ study documents physical 3D models, marker scanning and real-time AR overlays; student feedback mentions AR animation. The workflow also incorporates the developer’s description. Available controls and animations depend on the kit asset and platform.','Kajian TSJ mendokumenkan model fizikal 3D, imbasan penanda dan paparan AR masa nyata; maklum balas pelajar turut menyebut animasi AR. Aliran ini juga mengambil kira penerangan pembangun. Kawalan dan animasi yang tersedia bergantung pada aset kit serta platform.')}</p>
<section class="card spacer"><span class="label">WORKING DRAWING 2</span><h2>${t('Grounded in timber construction learning.','Berpaksikan pembelajaran pembinaan kayu.')}</h2><p>${t('The 2026 study places ARCHI-KIT in the timber construction topic of DA30123 Working Drawing 2 at Politeknik Port Dickson. This is the course code printed in that study; it should not be silently substituted for codes used in other curriculum versions.','Kajian 2026 menempatkan ARCHI-KIT dalam topik pembinaan kayu bagi DA30123 Working Drawing 2 di Politeknik Port Dickson. Kod ini mengikut kajian tersebut; ia tidak boleh diganti secara terus dengan kod daripada versi kurikulum lain.')}</p>${button('evidence/archi-kit-study-2026.pdf','Read the ARCHI-KIT study','Baca kajian ARCHI-KIT')}</section>
<section class="curriculum-banner"><div class="eyebrow">MICRO → MACRO</div><h2>${t('ARCHI-KIT helps learners examine how the parts connect.','ARCHI-KIT membantu pelajar meneliti hubungan antara komponen.')}</h2><p>${t('ARCHI-KIT focuses on timber joints and assembly through physical models and AR. ARCHI-SPACE extends the learning focus to whole-building designs and immersive spatial review. ARCHI-KIT is the physical–AR foundation, not the VR environment itself.','ARCHI-KIT memfokuskan sambungan kayu dan pemasangan melalui model fizikal serta AR. ARCHI-SPACE memperluas fokus pembelajaran kepada reka bentuk keseluruhan bangunan dan semakan ruang secara imersif. ARCHI-KIT ialah asas fizikal–AR, bukan persekitaran VR itu sendiri.')}</p><p>${t('The intended progression builds familiarity with 3D relationships and digital interaction before more complex spatial tasks. Transfer into VR is a pedagogical rationale—not a learning gain measured by the ARCHI-KIT survey.','Kesinambungan ini bertujuan membiasakan pelajar dengan hubungan 3D dan interaksi digital sebelum tugasan ruang yang lebih kompleks. Pemindahan kemahiran kepada VR ialah rasional pedagogi, bukan peningkatan yang diukur oleh soal selidik ARCHI-KIT.')}</p>${button('#sustain','See the Micro-to-Macro journey','Lihat perjalanan Micro-to-Macro',true)}</section>
${bridge('Explore what students reported about this physical–AR learning system.','Teroka maklum balas pelajar tentang sistem pembelajaran fizikal–AR ini.','#evidence')}`;}
function table(head,rows){return `<div class="tablewrap"><table><thead><tr>${head.map(h=>`<th scope="col">${h}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(c=>`<td>${c}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;}
function studentGallery(){return `<section class="student-gallery-panel"><div class="section-head"><h2>${t('Student gallery: implementation evidence.','Galeri pelajar: bukti pelaksanaan.')}</h2></div><p class="lead">${t('Use this gallery to show real implementation: student portfolios, group immersive projects and before/after development evidence.','Gunakan galeri ini untuk menunjukkan pelaksanaan sebenar: portfolio pelajar, projek imersif berkumpulan dan bukti pembangunan sebelum/selepas.')}</p><div class="student-gallery-grid"><article><span class="label">${t('PORTFOLIO','PORTFOLIO')}</span><h3>${t('Individual learning evidence','Bukti pembelajaran individu')}</h3><p>${t('Show curated student portfolio pages, process screenshots, model development and reflection.','Paparkan halaman portfolio pelajar, tangkapan skrin proses, pembangunan model dan refleksi.')}</p></article><article><span class="label">${t('GROUP PROJECT','PROJEK KUMPULAN')}</span><h3>${t('Immersive project output','Hasil projek imersif')}</h3><p>${t('Show the team’s VR/AR application, walkthrough or recorded demonstration linked to the design brief.','Paparkan aplikasi VR/AR kumpulan, walkthrough atau rakaman demonstrasi yang dikaitkan dengan brief reka bentuk.')}</p></article><article><span class="label">${t('BEFORE / AFTER','SEBELUM / SELEPAS')}</span><h3>${t('Visible transformation','Transformasi yang boleh dilihat')}</h3><p>${t('Compare the original design/model with the refined option, issue log and design decision.','Bandingkan reka bentuk/model asal dengan pilihan yang ditambah baik, log isu dan keputusan reka bentuk.')}</p></article></div><p class="source-note spacer">${t('Gallery items should use verified student work with permission. Placeholder cards are included so evidence can be wired in without changing the page structure later.','Item galeri perlu menggunakan hasil kerja pelajar yang disahkan dan mendapat kebenaran. Kad placeholder disediakan supaya bukti boleh dipautkan kemudian tanpa mengubah struktur halaman.')}</p></section>`;}
function archiKitOutcomeGallery(){return `<section class="archikit-outcome-panel"><div class="section-head"><h2>${t('ARCHI-KIT outcome evidence.','Bukti hasil ARCHI-KIT.')}</h2></div><p class="lead">${t('These photos belong in the ARCHI-KIT foundation section because they show the physical–digital construction outcome that prepares students before moving into ARCHI-SPACE.','Foto ini sesuai diletakkan dalam bahagian asas ARCHI-KIT kerana ia menunjukkan hasil pembinaan fizikal–digital yang menyediakan pelajar sebelum bergerak kepada ARCHI-SPACE.')}</p><div class="archikit-outcome-grid"><figure><img src="assets/implementation/archi-kit-outcome-01.jpg" loading="lazy" alt="${t('ARCHI-KIT outcome showing a large timber construction model with student','Hasil ARCHI-KIT yang menunjukkan model binaan kayu berskala besar bersama pelajar')}"><figcaption>${t('<strong>Physical–digital construction outcome.</strong> Students can see scale, timber components and construction relationships more clearly.','<strong>Hasil pembinaan fizikal–digital.</strong> Pelajar dapat melihat skala, komponen kayu dan hubungan binaan dengan lebih jelas.')}</figcaption></figure><figure><img src="assets/implementation/archi-kit-outcome-02.jpg" loading="lazy" alt="${t('ARCHI-KIT outcome showing timber structure and student scale reference','Hasil ARCHI-KIT yang menunjukkan struktur kayu dan rujukan skala pelajar')}"><figcaption>${t('<strong>Bridge to ARCHI-SPACE.</strong> The outcome supports the micro-to-macro progression from construction components to spatial experience.','<strong>Jambatan kepada ARCHI-SPACE.</strong> Hasil ini menyokong perkembangan mikro kepada makro daripada komponen binaan kepada pengalaman ruang.')}</figcaption></figure></div></section>`;}
function draftPresentationGallery(){const items=[['draft-presentation-01.jpg','FIRST DRAFT PRESENTATION','PEMBENTANGAN DRAF PERTAMA','Student-led immersive walkthrough','Walkthrough imersif kendalian pelajar','A student presents the first draft of an ARCHI-SPACE model on the large display, making spatial decisions visible for critique.','Pelajar membentangkan draf pertama model ARCHI-SPACE pada paparan besar supaya keputusan ruang dapat dikritik dengan jelas.'],['draft-presentation-02.jpg','COLLABORATIVE REVIEW','SEMAKAN KOLABORATIF','Group discussion during presentation','Perbincangan kumpulan semasa pembentangan','Students work in groups with laptops while the immersive model is projected for whole-class review and lecturer facilitation.','Pelajar bekerja dalam kumpulan menggunakan komputer riba sementara model imersif dipaparkan untuk semakan kelas dan fasilitasi pensyarah.'],['draft-presentation-03.jpg','WHOLE-CLASS CRITIQUE','KRITIK SELURUH KELAS','Shared spatial review','Semakan ruang bersama','The class observes the projected design environment, supporting peer comments before refinement of the next design version.','Kelas memerhati persekitaran reka bentuk yang dipaparkan, menyokong komen rakan sebelum penambahbaikan versi reka bentuk seterusnya.'],['draft-presentation-04.jpg','DESIGN EXPLANATION','PENERANGAN REKA BENTUK','Student explaining design options','Pelajar menerangkan pilihan reka bentuk','The presenter explains visual evidence from the model while peers and lecturer discuss the proposed spatial arrangement.','Pembentang menerangkan bukti visual daripada model sementara rakan dan pensyarah membincangkan cadangan susun atur ruang.'],['draft-presentation-05.jpg','IMMERSIVE EVIDENCE','BUKTI IMERSIF','Model view on the main screen','Paparan model pada skrin utama','The projected AR/VR view documents how students use ARCHI-SPACE to test and communicate early design ideas.','Paparan AR/VR yang dipancarkan mendokumenkan cara pelajar menggunakan ARCHI-SPACE untuk menguji dan menyampaikan idea reka bentuk awal.']];return `<section class="student-gallery-panel draft-gallery"><div class="section-head"><h2>${t('First draft presentation: immersive design review in action.','Pembentangan draf pertama: semakan reka bentuk imersif secara langsung.')}</h2></div><p class="lead">${t('These photos document students presenting their early ARCHI-SPACE design drafts during an immersive AR/VR teaching and learning session. The evidence strengthens Tab 06 by showing presentation, critique, peer discussion and lecturer facilitation before final refinement.','Foto ini mendokumenkan pelajar membentangkan draf awal reka bentuk ARCHI-SPACE semasa sesi pengajaran dan pembelajaran AR/VR imersif. Bukti ini mengukuhkan Tab 06 dengan menunjukkan pembentangan, kritik, perbincangan rakan dan fasilitasi pensyarah sebelum penambahbaikan akhir.')}</p><div class="draft-gallery-grid">${items.map(([img,label,bLabel,title,bTitle,desc,bDesc])=>`<article><img src="assets/implementation/${img}" loading="lazy" alt="${t(title,bTitle)}"><span class="label">${t(label,bLabel)}</span><h3>${t(title,bTitle)}</h3><p>${t(desc,bDesc)}</p></article>`).join('')}</div><p class="source-note spacer">${t('This section should be treated as classroom implementation evidence. Confirm public-use permission before final GitHub publication.','Bahagian ini perlu dianggap sebagai bukti pelaksanaan kelas. Sahkan kebenaran penggunaan awam sebelum penerbitan akhir di GitHub.')}</p></section>`;}
function implementationGallery(){const items=[['archi-space-lab-overview.jpg','ARCHI-SPACE ENVIRONMENT','PERSEKITARAN ARCHI-SPACE','Immersive learning stations','Stesen pembelajaran imersif','A prepared room with multiple screens, VR stations and flexible seating for active architectural learning.','Ruang pembelajaran dengan beberapa skrin, stesen VR dan tempat duduk fleksibel untuk pembelajaran seni bina aktif.'],['archi-space-lab-stations.jpg','FACILITY READINESS','KESEDIAAN FASILITI','Multi-station setup','Susun atur beberapa stesen','Screens and headsets are arranged so students can rotate between viewing, operating and discussing the immersive model.','Skrin dan headset disusun supaya pelajar boleh bergilir antara melihat, mengendalikan dan berbincang tentang model imersif.'],['archi-space-individual-vr.jpg','INDIVIDUAL TOOL OPERATION','PENGGUNAAN ALAT INDIVIDU','Student operating the VR view','Pelajar mengendalikan paparan VR','The learner uses a headset and controller while the external screen makes the immersive view visible for observation and guidance.','Pelajar menggunakan headset dan controller sementara skrin luaran memaparkan pengalaman imersif untuk pemerhatian dan bimbingan.'],['archi-space-group-session.jpg','COLLABORATIVE T&L','PdP KOLABORATIF','Peer support and facilitation','Sokongan rakan dan fasilitasi','Students participate in a shared immersive AR/VR session where peers observe, guide and discuss spatial decisions.','Pelajar menyertai sesi AR/VR imersif secara bersama, dengan rakan memerhati, membimbing dan membincangkan keputusan ruang.'],['archi-space-peer-review.jpg','DESIGN REVIEW','SEMAKAN REKA BENTUK','Group review at the stations','Semakan kumpulan di stesen','The activity supports design review through discussion around the displayed immersive environment and student-operated stations.','Aktiviti ini menyokong semakan reka bentuk melalui perbincangan sekitar persekitaran imersif yang dipaparkan dan stesen kendalian pelajar.'],['archi-space-tool-demo.jpg','DEMONSTRATION EVIDENCE','BUKTI DEMONSTRASI','Live tool demonstration','Demonstrasi alat secara langsung','A student demonstrates the immersive interface while the lecturer observes the process and learning interaction.','Pelajar mendemonstrasikan antara muka imersif sementara pensyarah memerhati proses dan interaksi pembelajaran.']];return `<section class="student-gallery-panel real-gallery"><div class="section-head"><h2>${t('Real implementation gallery.','Galeri pelaksanaan sebenar.')}</h2></div><p class="lead">${t('These photos show ARCHI-SPACE used during an immersive AR/VR teaching and learning session. These photos focus on ARCHI-SPACE use during the immersive AR/VR teaching and learning session.','Foto ini menunjukkan penggunaan ARCHI-SPACE semasa sesi pengajaran dan pembelajaran AR/VR imersif. Foto ini memfokuskan penggunaan ARCHI-SPACE semasa sesi pengajaran dan pembelajaran AR/VR imersif.')}</p><div class="implementation-gallery-grid">${items.map(([img,label,bLabel,title,bTitle,desc,bDesc])=>`<article><img src="assets/implementation/${img}" loading="lazy" alt="${t(title,bTitle)}"><span class="label">${t(label,bLabel)}</span><h3>${t(title,bTitle)}</h3><p>${t(desc,bDesc)}</p></article>`).join('')}</div><p class="source-note spacer">${t('Use these as verified implementation visuals only after confirming permission for public use. Avoid naming individual students unless written consent and portfolio links are confirmed.','Gunakan foto ini sebagai visual pelaksanaan yang disahkan selepas mendapat kebenaran penggunaan awam. Elakkan menamakan pelajar secara individu kecuali kebenaran bertulis dan pautan portfolio telah disahkan.')}</p></section>`;}
function stageContent(){const s=stages[stage];return `<div><span class="letter">${s.letter}</span><h2>${s.name}</h2><p>${t(s.en,s.bm)}</p>${badge('Proposed activity sequence','Cadangan urutan aktiviti')}</div><div><p>${t(s.desc,s.bdesc)}</p><div class="mini-heading">${t('What students do','Tindakan pelajar')}</div><ol>${(state.lang==='bm'?s.bstep:s.steps).map(v=>`<li>${v}</li>`).join('')}</ol><div class="mini-heading">${t('Learning evidence','Bukti pembelajaran')}</div><p>${t(s.output,s.boutput)}</p></div>`;}
function curriculumEvidence(){return `<details class="curriculum-evidence"><summary>${t('Explore the curriculum evidence','Lihat bukti kurikulum')}</summary><p>${t('Source documents reviewed: 31 August 2026. These records establish curriculum design and task requirements; they do not by themselves prove learning gains.','Dokumen sumber disemak pada 31 Ogos 2026. Rekod ini menerangkan reka bentuk kurikulum dan keperluan tugasan; rekod ini sahaja tidak membuktikan peningkatan pembelajaran.')}</p><ul>
<li>${button('https://drive.google.com/file/d/1hDooB9KC6uEeJlptPSUYNv60W5N8ydMv/view','Earlier CDIO integrated programme module','Modul program bersepadu CDIO terdahulu')}</li>
<li>${button('https://drive.google.com/file/d/12CpH_gaNifem1ia72Zleq3JDO_Unrpv0/view','DCA40462 course outline · 2026','Course Outline DCA40462 · 2026')}</li>
<li>${button('https://drive.google.com/file/d/1aRgV8ag6wTnZOEuHdXPs_620XaypM8SK/view','CIST · assessment and domain allocation','CIST · agihan pentaksiran dan domain')}</li>
<li>${button('https://drive.google.com/file/d/1GQ3wBy7RQF2WjxS-co1qVyLgW_1Wf23F/view','Project brief · reuse of Design Studio 3 models','Brief Project · penggunaan model Design Studio 3')}</li>
<li>${button('https://drive.google.com/file/d/15Ziz1c95QlEfxf1GQbaR4zSo5ZyudNbO/view','CDIO programme submission record · 2025','Rekod permohonan program CDIO · 2025')}</li></ul><p class="source-note">${t('These documents establish curriculum continuity, assessment structure and the CDIO programme record. The dedicated recognition panel below displays the verified award certificate separately.','Dokumen ini membuktikan kesinambungan kurikulum, struktur pentaksiran dan rekod program CDIO. Panel pengiktirafan khusus di bawah memaparkan sijil anugerah yang disahkan secara berasingan.')}</p></details>`;}
function model(){return pageHero('05',t('CURRICULUM → EXPERIENCE → REFLECTION','KURIKULUM → PENGALAMAN → REFLEKSI'),'One design.<br>A connected learning journey.','Satu reka bentuk.<br>Pembelajaran yang saling berhubung.','CDIO connects the disciplines. ARCHI-SPACE extends the spatial experience. SPACE guides observation, design decisions and reflection.','CDIO menghubungkan disiplin kursus. ARCHI-SPACE memperluas pengalaman ruang. SPACE memandu pemerhatian, keputusan reka bentuk dan refleksi.','hero-page-05','Connected curriculum methodology for immersive architectural learning','Metodologi kurikulum berhubung untuk pembelajaran seni bina imersif','General ARCHI-SPACE hero · curriculum, experience and reflection are connected.','Hero umum ARCHI-SPACE · kurikulum, pengalaman dan refleksi saling berhubung.','#challenge','See the development preview','Lihat pratonton pembangunan','#sustain','Revisit the evolution','Semak semula perkembangan')+`
<section class="curriculum-banner"><div class="eyebrow">${t('WHY IMMERSIVE XR BELONGS IN THE JOURNEY','MENGAPA IMMERSIVE XR MENJADI SEBAHAGIAN DARIPADA PEMBELAJARAN')}</div><h2>${t('Not an isolated technology lesson.','Bukan pembelajaran teknologi secara berasingan.')}</h2><p>${t('The DCA40462 Project brief asks students to reuse their DCA30364 Design Studio 3 model to develop a VR/AR application. The design becomes a learning resource for another course—not a disconnected software exercise.','Brief Project DCA40462 meminta pelajar menggunakan semula model DCA30364 Design Studio 3 untuk membangunkan aplikasi VR/AR. Reka bentuk tersebut menjadi sumber pembelajaran bagi kursus seterusnya, bukan sekadar latihan perisian yang terpisah.')}</p></section>
<section class="methodology-strip" aria-label="${t('Phase B methodology summary','Ringkasan metodologi Phase B')}">
<article><span>01</span><h3>${t('Curriculum continuity','Kesinambungan kurikulum')}</h3><p>${t('A studio model is carried forward into immersive technology tasks, so learning continues across courses.','Model studio diteruskan ke tugasan teknologi imersif supaya pembelajaran berlaku secara berkesinambungan antara kursus.')}</p></article>
<article><span>02</span><h3>${t('Experiential review','Semakan berasaskan pengalaman')}</h3><p>${t('Learners review the design as an experience, not only as a drawing or final render.','Pelajar menyemak reka bentuk sebagai pengalaman, bukan hanya sebagai lukisan atau render akhir.')}</p></article>
<article><span>03</span><h3>${t('Evidence-based reflection','Refleksi berasaskan bukti')}</h3><p>${t('Outputs must show tool operation, design reasoning, revision and individual contribution.','Hasil kerja perlu menunjukkan penggunaan alat, alasan reka bentuk, pindaan dan sumbangan individu.')}</p></article>
</section>
<div class="section-head"><h2>${t('CDIO: the curriculum connection.','CDIO: penghubung antara kursus.')}</h2></div>
<div class="curriculum-grid">
<article class="curriculum-card"><span class="label">01 · CONCEIVE + DESIGN</span><h3>Design Studio</h3><p>${t('Establish the brief, explore ideas and develop the spatial layout. The current project connection names DCA30364; the earlier integrated module names DCA30114.','Fahami brief, teroka idea dan hasilkan susun atur ruang. Hubungan projek semasa merujuk DCA30364; modul bersepadu terdahulu menggunakan DCA30114.')}</p><strong>${t('Evidence: concepts, plans and the design model.','Bukti: konsep, pelan dan model reka bentuk.')}</strong></article>
<article class="curriculum-card"><span class="label">02 · IMPLEMENT</span><h3>Working Drawings</h3><p>${t('Translate the design into coordinated technical drawings and details. This documentation stage supports the Implement phase; it is not a claim that the building has been constructed.','Terjemahkan reka bentuk kepada lukisan teknikal dan perincian yang selaras. Peringkat dokumentasi ini menyokong fasa Implement; bukan bermaksud bangunan tersebut telah dibina.')}</p><strong>${t('Evidence: working drawings and checked details.','Bukti: lukisan kerja dan perincian yang disemak.')}</strong></article>
<article class="curriculum-card"><span class="label">03 · OPERATE</span><h3>3D + Immersive XR</h3><p>${t('Use and demonstrate a digital environment to review a design. DCA40462 extends this opportunity through VR/AR application development, demonstration and teamwork.','Gunakan dan demonstrasikan persekitaran digital untuk menyemak reka bentuk. DCA40462 memperluas peluang ini melalui pembangunan aplikasi VR/AR, demonstrasi dan kerja berpasukan.')}</p><strong>${t('Evidence: application, demonstration video and design explanation.','Bukti: aplikasi, video demonstrasi dan penerangan reka bentuk.')}</strong></article></div>
<p class="source-note spacer">${t('This is a curriculum interpretation, not a rigid one-to-one CDIO mapping. The earlier Semester 3 module integrates DCA30114, DCA30123 and DCA30132. The current DCA40462 brief separately documents continuity from DCA30364. Course codes and outcomes must be read in their own curriculum versions.','Ini ialah tafsiran hubungan kurikulum, bukan pemetaan CDIO satu dengan satu yang tetap. Modul Semester 3 terdahulu mengintegrasikan DCA30114, DCA30123 dan DCA30132. Brief DCA40462 semasa pula mendokumenkan kesinambungan daripada DCA30364. Kod kursus dan hasil pembelajaran perlu dirujuk mengikut versi kurikulum masing-masing.')}</p>
<section class="cdio-flow-panel">
<div><span class="label">${t('METHOD IN PRACTICE','METODOLOGI DALAM AMALAN')}</span><h2>${t('One design moves through three learning lenses.','Satu reka bentuk melalui tiga lensa pembelajaran.')}</h2><p>${t('This makes ARCHI-SPACE easier for evaluators to understand: the innovation is not the headset alone, but the way a student design is progressively conceived, documented, experienced and explained.','Ini menjadikan ARCHI-SPACE lebih mudah difahami oleh penilai: inovasi bukan pada headset semata-mata, tetapi pada cara reka bentuk pelajar digagaskan, didokumenkan, dialami dan diterangkan secara berperingkat.')}</p></div>
${table([t('Learning lens','Lensa pembelajaran'),t('Course anchor','Kursus berasaskan bukti'),t('What becomes visible','Perkara yang dapat dilihat')],[[t('Design intention','Niat reka bentuk'),t('Design Studio 3','Design Studio 3'),t('Brief response, concept and spatial organisation','Respons brief, konsep dan susun atur ruang')],[t('Technical buildability','Kebolehbinaan teknikal'),t('Working Drawings','Working Drawings'),t('Details, components and coordinated documentation','Perincian, komponen dan dokumentasi yang diselaraskan')],[t('Spatial experience','Pengalaman ruang'),t('DCA40462 Immersive Technology in Architecture','DCA40462 Immersive Technology in Architecture'),t('Walkthrough, interaction, issue log and design justification','Walkthrough, interaksi, log isu dan justifikasi reka bentuk')]])}
</section>
<section class="card tint spacer"><h2>${t('From the brief to the immersive experience.','Daripada brief kepada pengalaman imersif.')}</h2><p>${t('Groups of 3–4 choose one project scope: sun path/shadow study, spatial visualisation, construction sequencing or user interaction with space. They develop a VR/AR application and submit a recorded demonstration through YouTube. VR equipment is optional in the brief.','Kumpulan 3–4 orang memilih satu skop projek: kajian laluan matahari/bayang, visualisasi ruang, urutan pembinaan atau interaksi pengguna dengan ruang. Mereka membangunkan aplikasi VR/AR dan menghantar rakaman demonstrasi melalui YouTube. Penggunaan peralatan VR adalah pilihan dalam brief.')}</p><p class="source-note">${t('A walkthrough supports design review; it does not independently establish ventilation performance, daylight adequacy or UBBL compliance. Such claims require appropriate technical analysis and checks.','Walkthrough menyokong semakan reka bentuk; ia tidak dengan sendirinya mengesahkan prestasi pengudaraan, kecukupan pencahayaan siang atau pematuhan UBBL. Dakwaan tersebut memerlukan analisis dan semakan teknikal yang sesuai.')}</p></section>
<div class="section-head"><h2>${t('SPACE: what learners do within the journey.','SPACE: tindakan pelajar sepanjang pembelajaran.')}</h2></div><p class="lead">${t('CDIO organises the curriculum connection. The proposed SPACE cycle makes the learning actions explicit. Learners can revisit any stage as their designs develop.','CDIO menyusun hubungan kurikulum. Cadangan kitaran SPACE memperjelas tindakan pembelajaran. Pelajar boleh kembali ke mana-mana peringkat sepanjang pembangunan reka bentuk.')}</p>
<div class="journey" aria-label="${t('SPACE stages','Peringkat SPACE')}">${stages.map((s,i)=>`<button data-stage="${i}" aria-pressed="${i===stage}" aria-controls="stage-detail"><small>0${i+1}</small><strong>${s.letter}</strong><span>${s.name}</span></button>`).join('')}</div><section id="stage-detail" class="stage" aria-live="polite">${stageContent()}</section>
<div class="section-head"><h2>${t('Assess the process—not just the render.','Nilai proses, bukan render sahaja.')}</h2></div><div class="grid2"><article class="card tint"><span class="label">DCA40462 · 2026</span><h3>Immersive Technology in Architecture</h3><p>${t('Semester 4 · Year 2 · 2 credits. The course outline specifies 100% continuous assessment.','Semester 4 · Tahun 2 · 2 kredit. Course Outline menetapkan 100% pentaksiran berterusan.')}</p><p><strong>CLO1 · P4 / PLO3</strong><br>${t('Accurate use of immersive software and equipment.','Penggunaan perisian dan peralatan imersif dengan tepat.')}</p><p><strong>CLO2 · A3 / PLO8</strong><br>${t('Leadership and responsible participation in a team.','Kepimpinan dan penyertaan yang bertanggungjawab dalam kumpulan.')}</p></article><article class="card"><h3>${t('Two views of the same assessment.','Dua sudut agihan pentaksiran yang sama.')}</h3>${table([t('Assessment task','Tugasan pentaksiran'),t('Weight','Wajaran')],[['e-Portfolio','50%'],['Project','50%']])}${table([t('Domain total (CIST)','Jumlah domain (CIST)'),t('Weight','Wajaran')],[[t('Psychomotor · P4','Psikomotor · P4'),'65%'],[t('Affective · A3','Afektif · A3'),'35%']])}<p class="source-note">${t('Task weights and domain weights are separate breakdowns of the same 100%; do not add the two tables together.','Wajaran tugasan dan domain ialah dua pecahan bagi jumlah 100% yang sama; jangan campurkan jumlah kedua-dua jadual.')}</p></article></div>
<section class="assessment-chain">
<article><h3>${t('e-Portfolio','e-Portfolio')}</h3><p>${t('Students curate process evidence, screenshots, model development and personal reflection.','Pelajar mengkurasi bukti proses, tangkapan skrin, pembangunan model dan refleksi kendiri.')}</p></article>
<article><h3>${t('Immersive Project','Projek Imersif')}</h3><p>${t('Students demonstrate a VR/AR application and explain how the digital experience supports design review.','Pelajar mendemonstrasikan aplikasi VR/AR dan menerangkan bagaimana pengalaman digital menyokong semakan reka bentuk.')}</p></article>
<article><h3>${t('Reflection & responsibility','Refleksi & tanggungjawab')}</h3><p>${t('The assessment captures both technical manipulation and responsible team participation.','Pentaksiran merangkumi kemahiran teknikal serta penyertaan kumpulan yang bertanggungjawab.')}</p></article>
</section>
${sltScaffolding()}
${curriculumEvidence()}${cdioRecognition()}
${bridge('See how a demonstration can support observation, review and documented design decisions.','Lihat bagaimana demonstrasi menyokong pemerhatian, semakan dan keputusan reka bentuk yang didokumentasikan.','#challenge')}`;}
const fields=[['brief','Client / design context','Klien / konteks reka bentuk'],['option','Preferred option and two reasons','Pilihan reka bentuk dan dua alasan'],['issue','Issue identified and visual evidence','Isu yang dikenal pasti dan bukti visual'],['revision','Proposed revision and verification needed','Cadangan pindaan dan pengesahan diperlukan'],['reflection','Your contribution and next improvement','Sumbangan anda dan penambahbaikan seterusnya']];
function challenge(){return pageHero('06',t('DEVELOPMENT PREVIEW','PRATONTON PEMBANGUNAN'),'See the process behind the design.','Lihat proses di sebalik reka bentuk.','A proposed learning challenge. Use the SeVRa demonstration as a case, then develop and document your own decisions.','Cadangan cabaran pembelajaran. Gunakan demonstrasi SeVRa sebagai kes, kemudian kembangkan dan dokumentasikan keputusan anda.','hero-page-06','Immersive design preview with virtual walkthrough and design options','Pratonton reka bentuk imersif dengan walkthrough maya dan pilihan reka bentuk','General ARCHI-SPACE hero · spatial experience, options and decision-making.','Hero umum ARCHI-SPACE · pengalaman ruang, pilihan dan pembuatan keputusan.','#resources','See what comes next','Lihat langkah seterusnya','#model','Back to the curriculum','Kembali kepada kurikulum')+`<div class="grid2"><article class="card tint"><span class="label">${t('YOUR BRIEF','BRIEF ANDA')}</span><h3>${t('A retreat with privacy and connection.','Ruang rehat yang menjaga privasi dan hubungan ruang.')}</h3><p>${t('Review a small retreat house for a family seeking privacy, outdoor views and comfortable shared spaces. Compare the alternatives; justify one choice and one revision. This brief is a teaching proposal, not a claim about the original SeVRa assignment.','Semak rumah percutian kecil untuk keluarga yang mengutamakan privasi, pandangan luar dan ruang bersama yang selesa. Bandingkan pilihan; berikan alasan bagi satu pilihan dan satu pindaan. Brief ini cadangan pengajaran, bukan dakwaan tentang tugasan asal SeVRa.')}</p></article><article class="card"><span class="label">${t('YOUR DELIVERABLES','HASIL TUGASAN')}</span><h3>${t('Make the decision visible.','Tunjukkan asas keputusan.')}</h3><p>${t('Submit an option comparison, one issue log, a revised model/drawing and a short individual reflection. Rotate operator, reviewer, client and recorder roles.','Hantar perbandingan pilihan, satu log isu, model/lukisan yang dipinda dan refleksi individu ringkas. Gilirkan peranan operator, penyemak, klien dan pencatat.')}</p>${badge('Lecturer approval before assessed use','Kelulusan pensyarah sebelum pentaksiran','pending')}</article></div><div class="section-head"><h2>${t('Watch with a purpose.','Tonton dengan tujuan.')}</h2></div><video class="video" controls preload="none" poster="assets/studio.jpg" aria-label="SeVRa VR and Design Options"><source src="assets/sevra.mp4" type="video/mp4">${t('Video unavailable. Use the text description below.','Video tidak tersedia. Gunakan penerangan teks di bawah.')}</video><p class="caption">${t('SeVRa · supplied student demonstration · 2:37. This web copy preserves the visual sequence; on-screen information is summarised below.','SeVRa · demonstrasi pelajar yang dibekalkan · 2:37. Salinan web mengekalkan urutan visual; maklumat pada skrin diringkaskan di bawah.')}</p><details><summary>${t('Read the visual description and task steps','Baca penerangan visual dan langkah tugasan')}</summary><div><p>${t('The video introduces design exploration, shows VR equipment setup and a client-style walkthrough, then presents an original model and three alternatives: Controlled Transparency, Honest Structure & Lightness, and Panoramic Living. It compares options and selects Option 1. It does not clearly demonstrate that all three alternatives were rebuilt and tested in VR.','Video memperkenalkan penerokaan reka bentuk, menunjukkan persediaan peralatan VR dan pengalaman seperti semakan klien, kemudian memaparkan model asal dan tiga pilihan: Controlled Transparency, Honest Structure & Lightness dan Panoramic Living. Pilihan dibandingkan dan Pilihan 1 dipilih. Video tidak menunjukkan dengan jelas bahawa ketiga-tiga pilihan telah dibina semula dan diuji dalam VR.')}</p><ol class="steps">${[t('Study the original model and the client brief.','Teliti model asal dan brief klien.'),t('Compare two alternatives using the same criteria.','Bandingkan dua pilihan menggunakan kriteria yang sama.'),t('Record one concern and a specific piece of visual evidence.','Catat satu isu dan bukti visual yang khusus.'),t('Propose a model revision and identify the checks it needs.','Cadangkan pindaan model dan semakan yang diperlukan.'),t('Explain your decision to a peer and record their feedback.','Terangkan keputusan kepada rakan dan rekod maklum balas.')].map(x=>`<li>${x}</li>`).join('')}</ol></div></details><div class="section-head"><h2>${t('SeVRa: observe, then question.','SeVRa: perhati, kemudian persoalkan.')}</h2></div><div class="subnav" aria-label="Model comparison"><button data-compare="base" aria-pressed="true">${t('Original model','Model asal')}</button><button data-compare="options" aria-pressed="false">${t('Selected design direction','Hala tuju reka bentuk dipilih')}</button></div><figure><img class="photo" id="compare-image" src="assets/base-model.jpg" alt="${t('Original building model shown in the supplied SeVRa video','Model bangunan asal dalam video SeVRa')}"><figcaption id="compare-caption" class="caption">${t('Video frame, approximately 1:34. This is a documented model, not a measured baseline score.','Bingkai video, sekitar 1:34. Ini model yang didokumentasikan, bukan skor awal yang diukur.')}</figcaption></figure><div class="banner"><p>${t('These frames illustrate design exploration. They do not establish that the selected image was rebuilt, technically validated or responsible for improved student attainment.','Bingkai ini menunjukkan penerokaan reka bentuk. Ia tidak membuktikan imej pilihan telah dibina semula, disahkan secara teknikal atau meningkatkan pencapaian pelajar.')}</p></div>${draftPresentationGallery()}${implementationGallery()}<section class="card worksheet spacer"><div class="eyebrow">${t('YOUR DESIGN DECISION LOG','LOG KEPUTUSAN REKA BENTUK')}</div><h2>${t('Think it through. Write it down.','Fikirkan. Catatkan.')}</h2><p class="source-note">${t('Saved on this browser only where storage is available. Nothing is submitted to a lecturer or database. Export your work before changing devices.','Disimpan dalam pelayar ini jika storan tersedia. Tiada jawapan dihantar kepada pensyarah atau pangkalan data. Eksport kerja sebelum menukar peranti.')}</p>${fields.map(([id,en,bm])=>`<label for="note-${id}">${t(en,bm)}</label><textarea id="note-${id}" data-note="${id}">${esc(state.notes[id]||'')}</textarea>`).join('')}<div class="actions"><button class="button primary" data-export>${t('Download decision log','Muat turun log keputusan')} ↓</button><button class="button" data-print>${t('Print / Save PDF','Cetak / Simpan PDF')}</button></div><p id="save-status" class="source-note"></p></section><details><summary>${t('Suggested assessment checklist—not an approved marking scheme','Cadangan senarai semak—bukan skema pemarkahan rasmi')}</summary><div>${table([t('Look for','Aspek'),t('Evidence','Bukti')],[[t('Tool operation','Penggunaan alat'),t('Individual demonstration with accurate commands','Demonstrasi individu menggunakan arahan dengan tepat')],[t('Design reasoning','Penaakulan reka bentuk'),t('Specific reasons tied to the client brief','Alasan khusus berdasarkan brief klien')],[t('Revision quality','Kualiti pindaan'),t('Change addresses the recorded issue','Perubahan menangani isu yang direkod')],[t('Team contribution','Sumbangan kumpulan'),t('Role rotation and individual reflection','Giliran peranan dan refleksi individu')]])}</div></details>${bridge('The demonstration opens the next question: how can the approach be refined and evaluated in practice?','Demonstrasi ini membuka persoalan seterusnya: bagaimana pendekatan ini boleh ditambah baik dan dinilai dalam amalan?','#resources')}`;}
function evidence(){return pageHero('03',t('WHAT WE DISCOVERED','APA YANG DIPELAJARI'),'What we learned shaped what came next.','Apa yang dipelajari membentuk langkah seterusnya.','Start with the published findings. Then distinguish the design opportunity from what the study actually measured.','Mulakan dengan dapatan yang diterbitkan. Kemudian bezakan peluang pembangunan daripada perkara yang benar-benar diukur dalam kajian.','hero-page-03','Abstract discovery of spatial learning gap and evidence','Penemuan abstrak tentang jurang pembelajaran ruang dan bukti','General ARCHI-SPACE hero · discovery, evidence and learning opportunity.','Hero umum ARCHI-SPACE · penemuan, bukti dan peluang pembelajaran.','#sustain','See what this leads to','Lihat langkah seterusnya','#why','Revisit the ARCHI-KIT foundation','Semak semula asas ARCHI-KIT')+`<div class="section-head"><h2>${t('The research foundation','Asas penyelidikan')}</h2>${badge('ARCHI-KIT · n = 50','ARCHI-KIT · n = 50','verified')}</div><div class="grid3">${[['4.26','86%',t('Helpfulness','Manfaat yang dirasai'),'43/50'],['4.18','82%',t('Engagement','Penglibatan'),'41/50'],['4.20','86%',t('Perceived effectiveness','Keberkesanan yang dirasai'),'43/50']].map(([m,p,l,n])=>`<article class="card"><span class="label">${l}</span><div class="metric">${m}<small> / 5</small></div><p>${t('Mean reported in the supplied study.','Min yang dilaporkan dalam kajian.')}</p><strong>${p}</strong> <small>${t('selected ratings 4–5','memilih skor 4–5')} (${n})</small><div class="bar"><span style="width:${p}"></span></div></article>`).join('')}</div><p class="source-note spacer">${t('Positive-response percentages calculated from the published frequencies, not percentage learning gains. These findings belong to ARCHI-KIT, not the proposed ARCHI-SPACE pilot. The usability mean is reported separately below with its source inconsistency.','Peratus respons positif dikira daripada frekuensi terbitan, bukan peratus peningkatan pembelajaran. Dapatan ini milik ARCHI-KIT, bukan percubaan ARCHI-SPACE yang dicadangkan. Min kebolehgunaan dipaparkan berasingan di bawah berserta ketidakselarasan dalam sumber.')}</p><article class="card spacer"><span class="label">${t('REPORTED USABILITY','KEBOLEHGUNAAN YANG DILAPORKAN')}</span><h3>3.98 / 5</h3><p>${t('The article reports this mean in section 4.1.1. Its table lists frequencies that imply 4.02, and the quoted item combines AR familiarity with perceived potential. The reported 3.98 is therefore shown with this qualification, not as a verified navigation-performance score.','Artikel melaporkan min ini dalam seksyen 4.1.1. Frekuensi dalam jadualnya menghasilkan min 4.02, dan item yang dipetik menggabungkan kebiasaan dengan AR serta potensi yang dirasai. Oleh itu, nilai 3.98 dipaparkan dengan penjelasan ini, bukan sebagai skor prestasi navigasi yang telah disahkan.')}</p></article>${button('evidence/archi-kit-study-2026.pdf','Read the study (PDF)','Baca kajian (PDF)')}<div class="section-head"><h2>${t('From findings to a development question.','Daripada dapatan kepada persoalan pembangunan.')}</h2></div><div class="grid2">${storyCard('FINDING','A promising foundation','Asas yang memberi petunjuk positif','Participants reported positive perceptions of ARCHI-KIT. These ratings describe their experience with that resource.','Peserta melaporkan persepsi positif terhadap ARCHI-KIT. Skor ini menggambarkan pengalaman mereka dengan sumber tersebut.','tint')}${storyCard('QUESTION','What could come next?','Apakah langkah seterusnya?','Could component-level exploration be connected to spatial review, option comparison and a justified design revision? This is a development question—not a result demonstrated by the ARCHI-KIT survey.','Bolehkah penerokaan komponen dihubungkan dengan semakan ruang, perbandingan pilihan dan pindaan reka bentuk berasas? Ini persoalan pembangunan, bukan dapatan yang dibuktikan oleh soal selidik ARCHI-KIT.')}</div><div class="section-head"><h2>${t('Curriculum evidence: a different kind of proof.','Bukti kurikulum: apa yang disokong oleh dokumen.')}</h2></div><p>${t('The course outline, CIST and project brief document how integrated learning is designed and assessed. They complement the ARCHI-KIT study; they are not additional survey results or proof of causal impact.','Course Outline, CIST dan brief projek mendokumenkan reka bentuk serta pentaksiran pembelajaran bersepadu. Dokumen ini melengkapi kajian ARCHI-KIT; bukan dapatan soal selidik tambahan atau bukti kesan sebab-akibat.')}</p>${curriculumEvidence()}${button('#model','See CDIO and SPACE in the course','Lihat CDIO dan SPACE dalam kursus')}${bridge('That question frames the extension from ARCHI-KIT to ARCHI-SPACE.','Persoalan itu membentuk pengembangan daripada ARCHI-KIT kepada ARCHI-SPACE.','#sustain')}`;}
function sustain(){return pageHero('04',t('THE EVOLUTION · MICRO TO MACRO','PERKEMBANGAN · MIKRO KEPADA MAKRO'),'From understanding the joint<br>to experiencing the space.','Daripada memahami sambungan<br>kepada mengalami ruang.','ARCHI-SPACE extends the learning focus. ARCHI-KIT remains the physical–AR foundation, not a tool replaced by VR.','ARCHI-SPACE memperluas fokus pembelajaran. ARCHI-KIT kekal sebagai asas fizikal–AR, bukan alat yang digantikan oleh VR.','hero-page-04','Micro to macro transformation from component to spatial environment','Transformasi mikro kepada makro daripada komponen kepada persekitaran ruang','General ARCHI-SPACE hero · movement from component understanding to spatial experience.','Hero umum ARCHI-SPACE · pergerakan daripada pemahaman komponen kepada pengalaman ruang.','#model','Explore CDIO + SPACE','Teroka CDIO + SPACE','#evidence','Back to the evidence','Kembali kepada bukti')+`
<ol class="phase-a-flow" aria-label="${t('Micro-to-Macro learning progression','Kesinambungan pembelajaran mikro kepada makro')}">
<li><span class="phase-a-tag">01 · MICRO</span><h2>ARCHI-KIT</h2><p>${t('Explore timber joints through physical models and AR. Focus on form, components and assembly.','Teroka sambungan kayu melalui model fizikal dan AR. Fokus pada bentuk, komponen dan pemasangan.')}</p><div class="phase-a-output"><strong>${t('Learning evidence','Bukti pembelajaran')}</strong><p>${t('Drawing–model matching and an explanation of the joint.','Padanan lukisan–model dan penerangan sambungan.')}</p></div></li>
<li><span class="phase-a-tag">02 · BRIDGE</span><h2>${t('Connect the representations','Hubungkan perwakilan')}</h2><p>${t('Relate component understanding to plans, sections and the building model. Identify where each component belongs in the overall design.','Hubungkan pemahaman komponen dengan pelan, keratan dan model bangunan. Kenal pasti kedudukan komponen dalam keseluruhan reka bentuk.')}</p><div class="phase-a-output"><strong>${t('Learning evidence','Bukti pembelajaran')}</strong><p>${t('Annotated drawings or a model comparison.','Lukisan beranotasi atau perbandingan model.')}</p></div></li>
<li><span class="phase-a-tag">03 · MACRO</span><h2>ARCHI-SPACE</h2><p>${t('Explore a building design in a digital or immersive environment. Review spatial experience and explain design decisions.','Teroka reka bentuk bangunan dalam persekitaran digital atau imersif. Semak pengalaman ruang dan jelaskan keputusan reka bentuk.')}</p><div class="phase-a-output"><strong>${t('Learning evidence','Bukti pembelajaran')}</strong><p>${t('Walkthrough, issue log, design revisions and reflection.','Walkthrough, log isu, pindaan dan refleksi.')}</p></div></li></ol>
<p class="source-note spacer">${t('A connected learning progression—not a claim that AR experience automatically produces VR mastery. The evidence examples describe learning outputs to document, not measured outcomes for every student.','Kesinambungan pembelajaran yang dirancang—bukan bermaksud pengalaman AR secara automatik menghasilkan penguasaan VR. Contoh bukti menerangkan hasil kerja untuk didokumentasikan, bukan pencapaian yang telah diukur bagi setiap pelajar.')}</p>
<section class="phase-a-shifts"><h2>${t('What develops across the journey?','Apakah yang berkembang sepanjang pembelajaran?')}</h2><ul><li>${t('Components → the whole space','Komponen → keseluruhan ruang')}</li><li>${t('Observing connections → examining user experience','Memerhatikan sambungan → meneliti pengalaman pengguna')}</li><li>${t('Explaining assembly → justifying design decisions','Menerangkan pemasangan → memberikan alasan bagi keputusan reka bentuk')}</li></ul></section>
<section class="curriculum-banner"><div class="eyebrow">DCA30364 → DCA40462</div><h2>${t('The same design becomes the next learning resource.','Reka bentuk yang sama menjadi sumber pembelajaran seterusnya.')}</h2><p>${t('The connection becomes explicit in the DCA40462 project brief: students reuse their DCA30364 Design Studio 3 model to develop a VR/AR application.','Kesinambungan ini dinyatakan dalam brief projek DCA40462: pelajar menggunakan semula model DCA30364 Design Studio 3 untuk membangunkan aplikasi VR/AR.')}</p>${button('#model','Explore CDIO + SPACE','Teroka CDIO + SPACE',true)}</section>
<p class="source-note">${t('This sequence shows the learning progression, not a dated historical timeline.','Urutan ini menunjukkan kesinambungan pembelajaran, bukan garis masa sejarah bertarikh.')}</p>
${bridge('See how CDIO connects the courses and SPACE guides learner actions.','Lihat bagaimana CDIO menghubungkan kursus dan SPACE memandu tindakan pelajar.','#model')}`;}
function resources(){const list=[['research',t('Published ARCHI-KIT study','Kajian ARCHI-KIT yang diterbitkan'),t('Read the study method, participant ratings and limitations.','Baca kaedah kajian, skor peserta dan batasan.'),'evidence/archi-kit-study-2026.pdf'],['media','SeVRa',t('Review the supplied demonstration and its visual description.','Semak demonstrasi yang dibekalkan serta penerangan visualnya.'),'#challenge'],['teaching',t('SPACE learning process','Proses pembelajaran SPACE'),t('Explore five learner actions and their suggested outputs.','Teroka lima tindakan pelajar dan cadangan hasilnya.'),'#model'],['teaching',t('Design decision log','Log keputusan reka bentuk'),t('Record and export decisions locally from the development preview.','Catat dan eksport keputusan secara setempat daripada pratonton pembangunan.'),'#challenge']];return pageHero('07',t('WHERE WE GO NEXT','HALA TUJU SETERUSNYA'),'An evolving model<br>for architectural learning.','Model yang terus berkembang<br>untuk pembelajaran seni bina.','The next stage is purposeful implementation, documentation and refinement—not simply adding more technology.','Peringkat seterusnya ialah pelaksanaan, dokumentasi dan penambahbaikan yang bertujuan—bukan sekadar menambah teknologi.','hero-page-07','Future-ready immersive architecture learning ecosystem','Ekosistem pembelajaran seni bina imersif yang bersedia untuk masa hadapan','General ARCHI-SPACE hero · future-ready implementation, evidence and refinement.','Hero umum ARCHI-SPACE · pelaksanaan, bukti dan penambahbaikan masa hadapan.','#overview','Return to the beginning','Kembali ke permulaan','#challenge','Revisit the development preview','Semak semula pratonton pembangunan')+`<div class="grid3">${storyCard('01','Refine access','Tambah baik akses','Plan device sharing, supported formats and screen-based alternatives. Different devices may offer different experiences.','Rancang perkongsian peranti, format yang disokong dan pilihan berasaskan skrin. Pengalaman mungkin berbeza mengikut peranti.')}${storyCard('02','Document the learning','Dokumentasikan pembelajaran','Collect matched work samples, individual tool demonstrations, decision logs and feedback.','Kumpul sampel kerja sepadan, demonstrasi penggunaan alat secara individu, log keputusan dan maklum balas.','tint')}${storyCard('03','Review and adapt','Semak dan sesuaikan','Record preparation time, equipment needs and what should change before another implementation.','Rekod masa persediaan, keperluan peralatan dan perubahan yang diperlukan sebelum pelaksanaan seterusnya.')}</div><div class="section-head"><h2>${t('Questions for the next development cycle.','Persoalan untuk kitaran pembangunan seterusnya.')}</h2></div>${table([t('Question','Soalan'),t('Evidence to explore','Bukti untuk diteliti')],[[t('Can learners operate the tools?','Bolehkah pelajar menggunakan alat?'),t('Individual practical demonstration','Demonstrasi amali individu')],[t('Can they explain a design decision?','Bolehkah mereka menerangkan keputusan reka bentuk?'),t('Reasons linked to the same brief and criteria','Alasan berdasarkan brief dan kriteria yang sama')],[t('Does the revision address the issue?','Adakah pindaan menangani isu?'),t('Original and revised work, with assessor feedback','Kerja asal dan dipinda, berserta maklum balas penilai')],[t('Can the learning be applied to another task?','Bolehkah pembelajaran diaplikasikan pada tugasan lain?'),t('A comparable new design task','Tugasan reka bentuk baharu yang setara')]])}<div class="section-head"><h2>${t('Preparing the next implementation','Persediaan pelaksanaan seterusnya')}</h2></div><section class="card checklist"><p class="source-note">${t('Optional planning checklist saved in this browser. Ticks describe your preparation, not verified project outcomes.','Senarai semak perancangan pilihan yang disimpan dalam pelayar ini. Tanda menunjukkan persediaan anda, bukan hasil projek yang disahkan.')}</p>${[[t('Confirm the course and cohort','Sahkan kursus dan kohort')],[t('Agree on the brief and assessment criteria','Persetujui brief dan kriteria pentaksiran')],[t('Test the available model and equipment','Uji model dan peralatan yang tersedia')],[t('Prepare accessible alternatives','Sediakan pilihan akses yang sesuai')],[t('Obtain permission for student work and photographs','Dapatkan kebenaran penggunaan hasil kerja dan foto pelajar')],[t('Check research figures against the source','Semak angka kajian dengan sumber')],[t('Schedule a review after implementation','Jadualkan semakan selepas pelaksanaan')]].map(([x],i)=>`<label><input type="checkbox" data-check="${i}" ${state.checks[i]?'checked':''}>${x}</label>`).join('')}<p id="check-total" class="source-note spacer"></p></section><div class="section-head"><h2>${t('Resources & credits','Sumber & kredit')}</h2></div><div class="subnav">${[['all','All','Semua'],['research','Research','Kajian'],['media','Media','Media'],['teaching','Teaching','Pengajaran']].map(([id,en,bm])=>`<button data-filter="${id}" aria-pressed="${filter===id}">${t(en,bm)}</button>`).join('')}</div><div class="grid2" id="resource-list">${list.map(([cat,title,desc,url])=>`<article class="card evidence-card" data-category="${cat}" ${filter!=='all'&&filter!==cat?'hidden':''}><h3>${title}</h3><p>${desc}</p><a class="button" href="${url}">${t('Open resource','Buka sumber')} ↗</a></article>`).join('')}</div><div class="banner"><p>${t('Research credit: the supplied ARCHI-KIT publication lists Norul Fazlina Khashim, Zurika Amnah @ Salmi Mohtar, Ahmad Qusyairi Ahmad Khairiri and Setiawan Hardono. ARCHI-SPACE team roles should be confirmed separately.','Kredit kajian: penerbitan ARCHI-KIT yang dibekalkan menyenaraikan Norul Fazlina Khashim, Zurika Amnah @ Salmi Mohtar, Ahmad Qusyairi Ahmad Khairiri dan Setiawan Hardono. Peranan pasukan ARCHI-SPACE perlu disahkan secara berasingan.')}</p></div><p class="source-note spacer">Politeknik Port Dickson · Diploma in Architecture</p><div class="story-bridge"><h3>${t('The story continues through use, reflection and improvement.','Perjalanan ini diteruskan melalui penggunaan, refleksi dan penambahbaikan.')}</h3>${button('#overview','Return to the beginning','Kembali ke permulaan')}</div>`;}
function sltScaffolding(){return `<section class="slt-panel"><div class="eyebrow">${t('DCA40462 · IMMERSIVE TECHNOLOGY IN ARCHITECTURE','DCA40462 · IMMERSIVE TECHNOLOGY IN ARCHITECTURE')}</div><div class="section-head"><h2>${t('80-hour Student Learning Time (SLT).','Masa Pembelajaran Pelajar (SLT) 80 jam.')}</h2></div><p class="lead">${t('DCA40462 is the accredited Immersive Technology in Architecture course; ARCHI-SPACE is the teaching and learning model used within it. This official SLT mapping shows how the course\'s 80 hours are structured, not a claim about the ARCHI-SPACE pilot itself.','DCA40462 ialah kursus Immersive Technology in Architecture yang diakreditasi; ARCHI-SPACE ialah model pengajaran dan pembelajaran yang digunakan di dalamnya. Pemetaan SLT rasmi ini menunjukkan struktur 80 jam kursus tersebut, bukan dakwaan tentang perintis ARCHI-SPACE itu sendiri.')}</p><div class="slt-stats"><article><span class="stat-num">42</span><span class="stat-label">${t('Face-to-face contact hours','Jam sentuhan bersemuka')}</span></article><article><span class="stat-num">38</span><span class="stat-label">${t('Independent learning hours','Jam pembelajaran kendiri')}</span></article><article><span class="stat-num">80</span><span class="stat-label">${t('Total Student Learning Time','Jumlah Masa Pembelajaran Pelajar')}</span></article><article><span class="stat-num">47.5%</span><span class="stat-label">${t('of SLT is self-paced, independent learning','SLT dilaksanakan secara kendiri dan bebas')}</span></article></div>${table([t('Module topic & assessment','Topik modul & pentaksiran'),t('Lecture (F2F)','Kuliah (F2F)'),t('Practical (F2F)','Amali (F2F)'),t('Independent learning (IL)','Pembelajaran kendiri (IL)'),t('Total SLT','Jumlah SLT')],[[t('1.0 Virtual Reality in Architecture','1.0 Realiti Maya dalam Senibina'),'4 hrs','8 hrs','8 hrs','20 hrs'],[t('2.0 Augmented Reality in Architecture','2.0 Realiti Terimbuh dalam Senibina'),'5 hrs','9 hrs','11 hrs','25 hrs'],[t('3.0 Mixed Reality in Architecture','3.0 Realiti Bercampur dalam Senibina'),'5 hrs','9 hrs','13 hrs','27 hrs'],[t('E-Portfolio (Continuous Assessment)','E-Portfolio (Pentaksiran Berterusan)'),'1 hr','—','3 hrs','4 hrs'],[t('Immersive Project (Continuous Assessment)','Projek Imersif (Pentaksiran Berterusan)'),'1 hr','—','3 hrs','4 hrs']])}<p class="source-note">${t('Figures reproduced from the DCA40462 course specification (grand totals: 16 lecture + 26 practical + 38 independent learning = 80 hours). Confirm against the current polytechnic syllabus before external publication.','Angka dipetik daripada spesifikasi kursus DCA40462 (jumlah keseluruhan: 16 jam kuliah + 26 jam amali + 38 jam pembelajaran kendiri = 80 jam). Sahkan dengan silibus politeknik semasa sebelum penerbitan awam.')}</p><div class="section-head"><h2>${t('Scaffolding: the co-authored studio guides.','Perancah: panduan studio yang dikarya bersama.')}</h2></div><p class="lead">${t('Two published reference guides give students a structured path through design studio before they move into digital modelling and immersive review.','Dua panduan rujukan terbitan memberi pelajar laluan berstruktur melalui studio reka bentuk sebelum mereka beralih kepada pemodelan digital dan semakan imersif.')}</p><div class="scaffold-grid"><article class="scaffold-card"><span class="label">${t('SCAFFOLDING · BOOK A','PERANCAH · BUKU A')}</span><h3>The Architectural Programme</h3><span class="meta">${t('A Guide to Understand Project Brief · 2023 · eISBN 978-629-7643-07-6','Panduan Memahami Brief Projek · 2023 · eISBN 978-629-7643-07-6')}</span><p>${t('The student\'s first step in the design studio: breaking down a project brief through space analysis, user demographics and precedent review, then converting it into a structured, executable architectural programme.','Langkah pertama pelajar dalam studio reka bentuk: memecahkan brief projek melalui analisis ruang, demografi pengguna dan kajian preseden, kemudian menukarkannya kepada program seni bina yang berstruktur dan boleh dilaksanakan.')}</p><p class="authors">${t('Authors','Penulis')}: Zurika Amnah @ Salmi Binti Mohtar, Mahanim Binti Abdullah Sadali, Ahmad Qusyairi Bin Ahmad Khairiri</p></article><article class="scaffold-card"><span class="label">${t('SCAFFOLDING · BOOK B','PERANCAH · BUKU B')}</span><h3>Design Process</h3><span class="meta">${t('A Guide to Successful Building Design · 2026','Panduan Reka Bentuk Bangunan Berjaya · 2026')}</span><p>${t('Maps the 14-week studio journey from client brief to final presentation, forming a continuity pair with Book A and grounding later VR/AR model revisions in real site constraints and standards such as the Uniform Building By-Laws.','Memetakan perjalanan studio 14 minggu daripada brief klien hingga pembentangan akhir, membentuk pasangan kesinambungan dengan Buku A serta mengasaskan pindaan model VR/AR kemudian pada kekangan tapak sebenar dan standard seperti Uniform Building By-Laws.')}</p><p class="authors">${t('Authors','Penulis')}: Zurika Amnah @ Salmi, Mahanim Abdullah, Ahmad Qusyairi</p><details><summary>${t('See the 14-week topic breakdown','Lihat pecahan topik 14 minggu')}</summary><ol class="steps"><li><strong>${t('The Programme','Program')} · ${t('Weeks 1–3','Minggu 1–3')}:</strong> ${t('Produce Schedule of Area (SoA) from the project brief.','Hasilkan Schedule of Area (SoA) daripada brief projek.')}</li><li><strong>${t('Site Analysis','Analisis Tapak')} · ${t('Weeks 4–5','Minggu 4–5')}:</strong> ${t('Conduct site analysis and produce a report.','Jalankan analisis tapak dan hasilkan laporan.')}</li><li><strong>${t('Site Proposal','Cadangan Tapak')} · ${t('Week 6','Minggu 6')}:</strong> ${t('Prepare design synthesis and produce site zoning.','Sediakan sintesis reka bentuk dan hasilkan zoning tapak.')}</li><li><strong>${t('Site Planning','Perancangan Tapak')} · ${t('Week 7','Minggu 7')}:</strong> ${t('Propose and produce a scaled site plan (1:250).','Cadangkan dan hasilkan pelan tapak berskala (1:250).')}</li><li><strong>${t('Design Consideration','Pertimbangan Reka Bentuk')} · ${t('Week 8','Minggu 8')}:</strong> ${t('Prepare a matrix diagram and sketch a bubble diagram.','Sediakan gambar rajah matriks dan lakar gambar rajah gelembung.')}</li><li><strong>${t('Building Design: Conceptual Ideas','Reka Bentuk Bangunan: Idea Konsep')} · ${t('Weeks 9–10','Minggu 9–10')}:</strong> ${t('Sketch conceptual ideas; produce schematic plans, sections and 3D massing mock-ups.','Lakar idea konsep; hasilkan pelan skematik, keratan dan model jisim 3D.')}</li><li><strong>${t('Building Design: Schematic Design','Reka Bentuk Bangunan: Reka Bentuk Skematik')} · ${t('Weeks 11–12','Minggu 11–12')}:</strong> ${t('Propose facade treatments; produce elevations and building services proposals.','Cadangkan rawatan fasad; hasilkan pandangan sisi dan cadangan sistem perkhidmatan bangunan.')}</li><li><strong>${t('Communication','Komunikasi')} · ${t('Weeks 13–14','Minggu 13–14')}:</strong> ${t('Compose the drawings into 3–4 presentation boards.','Susun lukisan menjadi 3–4 papan pembentangan.')}</li></ol></details></article></div></section>`;}
function storyCard(label,en,bm,desc,bdesc,cls=''){return `<article class="card ${cls}"><span class="label">${label}</span><h3>${t(en,bm)}</h3><p>${t(desc,bdesc)}</p></article>`;}
function bridge(en,bm,next){return `<aside class="story-bridge"><div class="eyebrow">${t('WHAT THIS LEADS TO','LANGKAH SETERUSNYA')}</div><p>${t(en,bm)}</p>${button(next,'Continue the story','Teruskan perjalanan',true)}</aside>`;}
function archiKitRecognition(){return `<section class="archikit-recognition-panel"><div class="recognition-intro"><span class="label">${t('EXTERNAL RECOGNITION · ARCHI-KIT','PENGIKTIRAFAN LUAR · ARCHI-KIT')}</span><h2>${t('Research credibility supported by documented recognition.','Kredibiliti kajian disokong oleh pengiktirafan yang didokumentasikan.')}</h2><p>${t('These records name ARCHI-KIT directly. They strengthen the innovation record but remain separate from the participant-perception findings reported above.','Rekod ini menamakan ARCHI-KIT secara langsung. Rekod ini mengukuhkan rekod inovasi tetapi kekal berasingan daripada dapatan persepsi peserta yang dilaporkan di atas.')}</p></div><div class="recognition-grid"><article><span class="award-year">2025</span><h3>${t('POLYCCOM Gold Medal','Pingat Emas POLYCCOM')}</h3><p>${t('Certificate naming Zurika Amnah @ Salmi Mohtar, Ahmad Qusyairi Ahmad Khairiri and Norul Fazlina Khashim for ARCHI-KIT.','Sijil yang menamakan Zurika Amnah @ Salmi Mohtar, Ahmad Qusyairi Ahmad Khairiri dan Norul Fazlina Khashim bagi ARCHI-KIT.')}</p>${button('https://drive.google.com/file/d/1ByPq9D8l3SMlcuIOduj1ebhksk6Q4u5b/view?usp=drivesdk','View certificate','Lihat sijil')}</article><article><span class="award-year">2025</span><h3>${t('Best Commercialisation Award','Anugerah Pengkomersialan Terbaik')}</h3><p>${t('POLYCCOM 2025 · Category 7: Teaching & Learning. The certificate explicitly identifies ARCHI-KIT.','POLYCCOM 2025 · Kategori 7: Pengajaran & Pembelajaran. Sijil tersebut menamakan ARCHI-KIT secara jelas.')}</p>${button('https://drive.google.com/file/d/1PjKuW4wCYKFofLgVpPJ-MFnG7Csqqp3V/view?usp=drivesdk','View certificate','Lihat sijil')}</article><article><span class="award-year">RESPEX25</span><h3>${t('Recognition record','Rekod pengiktirafan')}</h3><p>${t('Supporting award record retained in the ARCHI-KIT evidence folder. The card does not infer an award category beyond what is visible in the source image.','Rekod anugerah sokongan yang disimpan dalam folder bukti ARCHI-KIT. Kad ini tidak membuat andaian tentang kategori anugerah selain maklumat yang kelihatan pada imej sumber.')}</p>${button('https://drive.google.com/file/d/1KlGBSp6foU9LTytVCG5I6_RWQZQl6lIW/view?usp=drivesdk','Inspect source image','Semak imej sumber')}</article></div><p class="source-note">${t('Award records are evidence of external recognition; they are not additional measures of student learning gains.','Rekod anugerah ialah bukti pengiktirafan luar; rekod tersebut bukan ukuran tambahan bagi peningkatan pembelajaran pelajar.')}</p></section>`;}
function cdioRecognition(){return `<section class="cdio-recognition-panel"><figure><img src="assets/cdio-programme-award.jpg" alt="${t('Certificate for Most Consistent CDIO Practitioner by Academic Programme Award','Sijil Most Consistent CDIO Practitioner by Academic Programme Award')}" loading="lazy"></figure><div><span class="label">${t('PROGRAMME-LEVEL RECOGNITION · CDIO','PENGIKTIRAFAN PERINGKAT PROGRAM · CDIO')}</span><h2>${t('Most Consistent CDIO Practitioner by Academic Programme Award.','Most Consistent CDIO Practitioner by Academic Programme Award.')}</h2><p>${t('The certificate recognises the Diploma in Architecture, Politeknik Port Dickson, for its contribution as a consistent CDIO academic programme at the Malaysia CDIO Practitioners Conference, 9 September 2025, KSL Hotel, Johor Bahru.','Sijil ini mengiktiraf Diploma in Architecture, Politeknik Port Dickson, atas sumbangannya sebagai program akademik yang konsisten dalam pelaksanaan CDIO sempena Malaysia CDIO Practitioners Conference pada 9 September 2025 di KSL Hotel, Johor Bahru.')}</p><p class="source-note">${t('This is programme-level recognition supporting the curriculum context. It is not an ARCHI-KIT award and not a separate ARCHI-SPACE award.','Ini ialah pengiktirafan peringkat program yang menyokong konteks kurikulum. Ia bukan anugerah ARCHI-KIT dan bukan anugerah berasingan untuk ARCHI-SPACE.')}</p><div class="actions">${button('evidence/cdio-programme-award-2025.pdf','View certificate and submission evidence','Lihat sijil dan bukti permohonan',true)}${button('https://drive.google.com/file/d/15Ziz1c95QlEfxf1GQbaR4zSo5ZyudNbO/view?usp=drivesdk','Open original in Drive','Buka fail asal di Drive')}</div></div></section>`;}
function evidenceEnhanced(){
  const methodRows=[
    [t('Institution & course','Institusi & kursus'),t('Politeknik Port Dickson · DA30123 Working Drawing 2 (timber construction topic)','Politeknik Port Dickson · DA30123 Working Drawing 2 (topik pembinaan kayu)')],
    [t('Research design','Reka bentuk kajian'),t('Convergent parallel mixed methods within a Design-Based Research (DBR) framework','Kaedah campuran selari konvergen dalam rangka kerja Design-Based Research (DBR)')],
    [t('Participants','Peserta'),t('50 TVET students; purposive sampling of students who had completed hands-on ARCHI-KIT sessions','50 pelajar TVET; persampelan bertujuan bagi pelajar yang telah menyelesaikan sesi amali ARCHI-KIT')],
    [t('Instrument','Instrumen'),t('Structured Google Forms questionnaire adapting the UEQ; Likert-scale and open-ended items across background, ARCHI-KIT experience and learning impact','Soal selidik Google Forms berstruktur yang mengadaptasi UEQ; item skala Likert dan soalan terbuka merangkumi latar belakang, pengalaman ARCHI-KIT dan impak pembelajaran')],
    [t('Data collection','Pengumpulan data'),t('Completed after the training sessions over one week; supported by classroom observation notes, structured observation forms and video recordings','Dilengkapkan selepas sesi latihan dalam tempoh seminggu; disokong oleh nota pemerhatian kelas, borang pemerhatian berstruktur dan rakaman video')],
    [t('Analysis','Analisis'),t('Descriptive statistics (frequency, mean and SD) in Microsoft Excel; manual thematic analysis of open-ended responses','Statistik deskriptif (frekuensi, min dan SP) menggunakan Microsoft Excel; analisis tematik manual bagi respons terbuka')]
  ];
  const metrics=[
    ['4.26','86%',t('Helpfulness','Manfaat yang dirasai'),'43/50'],
    ['4.18','82%',t('Engagement','Penglibatan'),'41/50'],
    ['4.20','86%',t('Perceived effectiveness','Keberkesanan yang dirasai'),'43/50']
  ];
  return pageHero('03',t('ARCHI-KIT EVIDENCE','BUKTI ARCHI-KIT'),'Published research.<br>Documented recognition.','Kajian diterbitkan.<br>Pengiktirafan didokumentasikan.','This page establishes the credibility of ARCHI-KIT through its published study, transparent data checks, stated limitations and external recognition records.','Halaman ini membuktikan kredibiliti ARCHI-KIT melalui kajian terbitan, semakan data yang telus, batasan yang dinyatakan dan rekod pengiktirafan luar.','hero-page-03','Abstract discovery of spatial learning gap and evidence','Penemuan abstrak tentang jurang pembelajaran ruang dan bukti','ARCHI-KIT evidence · research findings and documented recognition.','Bukti ARCHI-KIT · dapatan kajian dan pengiktirafan yang didokumentasikan.','#study-method','Review the study method','Semak kaedah kajian','#archikit-recognition','See ARCHI-KIT recognition','Lihat pengiktirafan ARCHI-KIT')+`
  <section class="evidence-identity-panel">
    <div><span class="eyebrow">${t('PUBLISHED EVIDENCE · ARCHI-KIT','BUKTI DITERBITKAN · ARCHI-KIT')}</span><h2>${t('Evidence first. Extension second.','Bukti dahulu. Pengembangan kemudian.')}</h2><p>${t('This page reports what the 2026 ARCHI-KIT study measured. ARCHI-SPACE is presented only as the next development question—not as an outcome proven by that survey.','Halaman ini melaporkan perkara yang diukur dalam kajian ARCHI-KIT 2026. ARCHI-SPACE hanya dikemukakan sebagai persoalan pembangunan seterusnya—bukan hasil yang dibuktikan oleh soal selidik tersebut.')}</p></div>
    <div class="evidence-integrity-mark"><strong>50</strong><span>${t('valid student responses','respons pelajar yang sah')}</span>${badge('Source checked','Sumber disemak','verified')}</div>
  </section>
  <div class="section-head"><h2>${t('The research foundation','Asas penyelidikan')}</h2>${badge('ARCHI-KIT · n = 50','ARCHI-KIT · n = 50','verified')}</div>
  <div class="grid3 evidence-metrics">${metrics.map(([m,p,l,n])=>`<article class="card"><span class="label">${l}</span><div class="metric">${m}<small> / 5</small></div><p>${t('Mean reported in the published study.','Min yang dilaporkan dalam kajian terbitan.')}</p><strong>${p}</strong> <small>${t('selected ratings 4–5','memilih skor 4–5')} (${n})</small><div class="bar"><span style="width:${p}"></span></div></article>`).join('')}</div>
  <p class="source-note spacer">${t('Positive-response percentages are calculated from the published frequencies; they are not percentage learning gains. All three findings belong to ARCHI-KIT, not ARCHI-SPACE.','Peratus respons positif dikira daripada frekuensi terbitan; angka tersebut bukan peratus peningkatan pembelajaran. Ketiga-tiga dapatan ini milik ARCHI-KIT, bukan ARCHI-SPACE.')}</p>
  <section class="study-method-panel" id="study-method"><div class="study-method-intro"><span class="label">${t('STUDY AT A GLANCE','RINGKASAN KAJIAN')}</span><h2>${t('How the ARCHI-KIT study was conducted.','Bagaimana kajian ARCHI-KIT dijalankan.')}</h2><p>${t('These details come directly from the published article, allowing reviewers to assess the findings against the actual method—not only the headline numbers.','Butiran ini diambil terus daripada artikel yang diterbitkan supaya penilai dapat menilai dapatan berdasarkan kaedah sebenar—bukan sekadar angka utama.')}</p></div>${table([t('Aspect','Aspek'),t('Detail','Butiran')],methodRows)}</section>
  <section class="usability-audit"><div><span class="label">${t('TRANSPARENT DATA CHECK','SEMAKAN DATA TELUS')}</span><h2>${t('One item, two values.','Satu item, dua nilai.')}</h2><p>${t('The difference is disclosed rather than silently corrected. The item itself combines AR familiarity with perceived potential, so neither value should be presented as a verified navigation-performance score.','Perbezaan ini dinyatakan secara terbuka dan bukan dibetulkan secara senyap. Item tersebut menggabungkan kebiasaan terhadap AR dengan potensi yang dirasai, maka kedua-dua nilai tidak wajar dipersembahkan sebagai skor prestasi navigasi yang telah disahkan.')}</p></div><div class="usability-compare"><article><span>${t('Article text','Teks artikel')}</span><strong>3.98</strong><small>/ 5 · SD 1.03</small></article><article><span>${t('Recalculated from frequencies','Dikira semula daripada frekuensi')}</span><strong>4.02</strong><small>/ 5 · (2, 3, 7, 18, 20)</small></article></div></section>
  <section class="publication-proof"><figure><img src="assets/evidence-study-cover.jpg" alt="${t('First page of the published 2026 ARCHI-KIT study','Halaman pertama kajian ARCHI-KIT 2026 yang diterbitkan')}" loading="lazy"></figure><div><span class="label">${t('PUBLISHED SOURCE','SUMBER DITERBITKAN')}</span><h2>${t('Inspect the evidence behind the numbers.','Semak bukti di sebalik angka.')}</h2><p>Khashim, N. F., Mohtar, Z. A. @ S., Khairiri, A. Q. A., &amp; Hardono, S. (2026). <em>Enhancing student engagement and skills in timber construction through ARCHI-KIT: A 3D model and augmented reality (AR) approach.</em> Tropical Scientific Journal, 5(2), 196–208.</p>${button('evidence/archi-kit-study-2026.pdf','Read the full study (PDF)','Baca kajian penuh (PDF)',true)}</div></section>
  <section class="limitations-panel"><span class="label">${t('EVIDENCE BOUNDARY','SEMPADAN BUKTI')}</span><h2>${t('What this study does—and does not—establish.','Perkara yang dibuktikan—dan tidak dibuktikan—oleh kajian ini.')}</h2><div class="limitations-grid"><article><strong>${t('Single context','Satu konteks')}</strong><p>${t('The sample came from one course at one institution, limiting generalisation to other cohorts and settings.','Sampel datang daripada satu kursus di satu institusi, maka generalisasi kepada kohort dan konteks lain adalah terhad.')}</p></article><article><strong>${t('Purposive sample','Sampel bertujuan')}</strong><p>${t('Only students who had completed ARCHI-KIT sessions were selected; there was no random assignment or comparison group.','Hanya pelajar yang telah mengikuti sesi ARCHI-KIT dipilih; tiada pengagihan rawak atau kumpulan perbandingan.')}</p></article><article><strong>${t('Perception-led evidence','Bukti berasaskan persepsi')}</strong><p>${t('The main quantitative results are self-reported ratings supported by observations—not direct pre/post learning-gain measures.','Dapatan kuantitatif utama ialah penilaian kendiri yang disokong pemerhatian—bukan ukuran langsung peningkatan pembelajaran pra/pasca.')}</p></article></div></section>
  <div id="archikit-recognition">${archiKitRecognition()}</div>${bridge('With the ARCHI-KIT foundation established, the next page explains the shift from component understanding to spatial experience.','Setelah asas ARCHI-KIT dibuktikan, halaman seterusnya menerangkan peralihan daripada pemahaman komponen kepada pengalaman ruang.','#sustain')}`;
}
function challengeEnhanced(){
  const impactLenses=[
    ['01',t('Spatial understanding','Pemahaman ruang'),t('Students reflected on experiencing scale, layout and relationships between spaces through VR/AR.','Pelajar membuat refleksi tentang pengalaman skala, susun atur dan hubungan antara ruang melalui VR/AR.')],
    ['02',t('XR capability','Keupayaan XR'),t('The instrument records perceived confidence with XR software, VR equipment and digital presentation.','Instrumen merekodkan keyakinan yang dirasai terhadap perisian XR, peralatan VR dan pembentangan digital.')],
    ['03',t('Design judgement','Pertimbangan reka bentuk'),t('Responses address identifying design issues, making decisions and considering real users.','Respons merangkumi pengenalpastian isu reka bentuk, pembuatan keputusan dan pertimbangan pengguna sebenar.')],
    ['04',t('Collaboration','Kolaborasi'),t('Students reflected on teamwork, communication, responsibility and respect for peer views.','Pelajar membuat refleksi tentang kerja berpasukan, komunikasi, tanggungjawab dan penghargaan terhadap pandangan rakan.')],
    ['05',t('Industry readiness','Kesediaan industri'),t('The reflection asks whether learners feel more prepared to use immersive technologies in industry.','Refleksi menilai sama ada pelajar berasa lebih bersedia menggunakan teknologi imersif dalam industri.')],
    ['06',t('Sustainability','Kelestarian'),t('Items connect the project with Universal Design, SDG 4, SDG 9 and reduced paper use through e-portfolios.','Item menghubungkan projek dengan Universal Design, SDG 4, SDG 9 dan pengurangan penggunaan kertas melalui e-portfolio.')]
  ];
  return pageHero('06',t('ARCHI-SPACE IN PRACTICE','ARCHI-SPACE DALAM AMALAN'),'From immersive experience<br>to visible learning evidence.','Daripada pengalaman imersif<br>kepada bukti pembelajaran yang nyata.','This page brings together implementation, student projects, design-process portfolios and student-reported reflections. Each evidence type is labelled so evaluators can see what it establishes—and what it does not.','Halaman ini menghimpunkan pelaksanaan, projek pelajar, portfolio proses reka bentuk dan refleksi kendiri pelajar. Setiap jenis bukti dilabel supaya penilai dapat melihat perkara yang dibuktikan—dan yang tidak dibuktikan.','hero-page-06','Students presenting and reviewing immersive architectural work','Pelajar membentangkan dan menyemak hasil seni bina imersif','ARCHI-SPACE implementation · student work, process and reflection evidence.','Pelaksanaan ARCHI-SPACE · bukti hasil, proses dan refleksi pelajar.','#xr-projects','Explore student projects','Teroka projek pelajar','#xr-impact','See reflection evidence','Lihat bukti refleksi')+`
  <section class="xr-orientation"><div><span class="label">${t('HOW TO READ THIS PAGE','CARA MEMBACA HALAMAN INI')}</span><h2>${t('Four evidence lenses. One connected implementation story.','Empat lensa bukti. Satu cerita pelaksanaan yang saling berhubung.')}</h2><p>${t('The layout moves from what students experienced to what they created, documented and reported. Supporting galleries and tools remain available without overwhelming the main evidence path.','Susun atur bergerak daripada pengalaman pelajar kepada hasil yang dicipta, didokumentasikan dan dilaporkan. Galeri serta alat sokongan kekal tersedia tanpa membebankan laluan bukti utama.')}</p></div><ol class="xr-evidence-map"><li><span>01</span><strong>${t('Experience','Alami')}</strong><small>${t('Real sessions','Sesi sebenar')}</small></li><li><span>02</span><strong>${t('Create','Hasilkan')}</strong><small>${t('XR projects','Projek XR')}</small></li><li><span>03</span><strong>${t('Document','Dokumentasi')}</strong><small>e-Portfolio</small></li><li><span>04</span><strong>${t('Reflect','Refleksi')}</strong><small>${t('Student voice','Suara pelajar')}</small></li></ol></section>

  <section class="xr-section" id="xr-projects"><div class="xr-section-copy"><span class="label">${t('EVIDENCE 01 · IMMERSIVE PROJECTS','BUKTI 01 · PROJEK IMERSIF')}</span><h2>${t('Students demonstrate the experience they built.','Pelajar mendemonstrasikan pengalaman yang dibangunkan.')}</h2><p>${t('The project evidence shows student-produced immersive walkthroughs and design-option communication. It demonstrates technical and presentation activity; it does not independently prove building performance or learning gains.','Bukti projek menunjukkan walkthrough imersif dan komunikasi pilihan reka bentuk yang dihasilkan oleh pelajar. Bukti ini menunjukkan aktiviti teknikal serta pembentangan; ia tidak dengan sendirinya membuktikan prestasi bangunan atau peningkatan pembelajaran.')}</p></div><div class="xr-feature-grid"><article class="xr-video-card"><video controls preload="metadata" poster="assets/studio.jpg" aria-label="SeVRa VR and Design Options"><source src="assets/sevra.mp4" type="video/mp4">${t('Video unavailable. Use the evidence links and text description.','Video tidak tersedia. Gunakan pautan bukti dan penerangan teks.')}</video><div><span class="label">SeVRa · ${t('DEVELOPMENT EXAMPLE','CONTOH PEMBANGUNAN')}</span><h3>VR and Design Options</h3><p>${t('A student demonstration of immersive walkthrough and design-option comparison. The visual sequence is retained as a development example.','Demonstrasi pelajar tentang walkthrough imersif dan perbandingan pilihan reka bentuk. Urutan visual dikekalkan sebagai contoh pembangunan.')}</p></div></article><div class="xr-link-stack"><article><span class="label">${t('PROJECT TOUR','LAWATAN PROJEK')}</span><h3>Immersive Technology</h3><p>${t('Full project-tour video retained in the evidence repository.','Video lawatan projek penuh disimpan dalam repositori bukti.')}</p>${button('https://drive.google.com/file/d/1pzzNqr1huTcRlilMNo0kuwyJy1sungwo/view?usp=drivesdk','Open project tour','Buka lawatan projek')}</article><article><span class="label">${t('GROUP OUTPUTS','HASIL KUMPULAN')}</span><h3>${t('YouTube demonstrations','Demonstrasi YouTube')}</h3><div class="compact-actions">${button('https://www.youtube.com/watch?v=HOucPkX37jw','Group sample 1','Sampel kumpulan 1')}${button('https://www.youtube.com/watch?v=3lEedAJunqM','Group sample 2','Sampel kumpulan 2')}</div></article></div></div>
  <details class="xr-detail"><summary>${t('Inspect the SeVRa model comparison and evidence boundary','Semak perbandingan model SeVRa dan sempadan bukti')}</summary><div><p>${t('The supplied demonstration presents an original model and alternative design directions. These visuals support design discussion; they do not establish that every alternative was rebuilt, technically validated or responsible for improved attainment.','Demonstrasi yang dibekalkan memaparkan model asal dan beberapa hala tuju reka bentuk. Visual ini menyokong perbincangan reka bentuk; ia tidak membuktikan bahawa setiap pilihan dibina semula, disahkan secara teknikal atau meningkatkan pencapaian.')}</p><div class="subnav" aria-label="Model comparison"><button data-compare="base" aria-pressed="true">${t('Original model','Model asal')}</button><button data-compare="options" aria-pressed="false">${t('Selected design direction','Hala tuju reka bentuk dipilih')}</button></div><figure><img class="photo" id="compare-image" src="assets/base-model.jpg" alt="${t('Original building model shown in the supplied SeVRa video','Model bangunan asal dalam video SeVRa')}"><figcaption id="compare-caption" class="caption">${t('Documented visual frame—not a measured baseline score.','Bingkai visual yang didokumentasikan—bukan skor garis dasar yang diukur.')}</figcaption></figure></div></details></section>

  <section class="xr-section portfolio-section"><div class="xr-section-copy"><span class="label">${t('EVIDENCE 02 · DESIGN PROCESS','BUKTI 02 · PROSES REKA BENTUK')}</span><h2>${t('The e-portfolio makes the learning journey inspectable.','e-Portfolio menjadikan perjalanan pembelajaran boleh disemak.')}</h2><p>${t('Each featured case connects process documentation with a published student portfolio. Names are shown only for the two supplied portfolio examples; registration numbers are intentionally excluded. Public display remains subject to confirmed student permission.','Setiap kes pilihan menghubungkan dokumentasi proses dengan portfolio pelajar yang diterbitkan. Nama hanya dipaparkan bagi dua contoh portfolio yang dibekalkan; nombor pendaftaran sengaja tidak disertakan. Paparan awam tertakluk pada pengesahan kebenaran pelajar.')}</p></div><div class="portfolio-evidence-grid"><article><span class="portfolio-index">01</span><h3>Nur Shasha</h3><p>${t('Learning journal, PDF e-portfolio and supporting recognition records are organised in the student evidence folder.','Jurnal pembelajaran, e-portfolio PDF dan rekod pengiktirafan sokongan disusun dalam folder bukti pelajar.')}</p><div class="compact-actions">${button('https://nurshasha.my.canva.site/','Open live portfolio','Buka portfolio langsung',true)}${button('https://drive.google.com/file/d/1PaqjIDEU_YmNw8iwG-ao47ZQm7LsytiF/view?usp=drivesdk','Inspect PDF sample','Semak sampel PDF')}${button('https://drive.google.com/file/d/11EE94E2C-IhwUnES-SnNhN_dVjTrnlno/view?usp=drivesdk','View design journal','Lihat jurnal reka bentuk')}</div></article><article><span class="portfolio-index">02</span><h3>Nur Batrisyia</h3><p>${t('The second case provides a live portfolio and PDF evidence of the student’s immersive learning documentation.','Kes kedua menyediakan portfolio langsung dan bukti PDF bagi dokumentasi pembelajaran imersif pelajar.')}</p><div class="compact-actions">${button('https://katanamaammm.my.canva.site/batrisyiaasri','Open live portfolio','Buka portfolio langsung',true)}${button('https://drive.google.com/file/d/1MPRY35ka_aK4oq6R7UQB0ELHLbA52jz0/view?usp=drivesdk','Inspect PDF sample','Semak sampel PDF')}</div></article></div><p class="source-note">${t('Portfolio authorship, award titles and public-use permission should be confirmed before final external publication.','Kepengarangan portfolio, tajuk anugerah dan kebenaran penggunaan awam perlu disahkan sebelum penerbitan luar yang muktamad.')}</p></section>

  <section class="xr-impact-panel" id="xr-impact"><div class="xr-impact-head"><span class="label">${t('EVIDENCE 03 · STUDENT-REPORTED REFLECTION','BUKTI 03 · REFLEKSI KENDIRI PELAJAR')}</span><h2>${t('What students reported after the Immersive-XR project.','Perkara yang dilaporkan pelajar selepas projek Imersif-XR.')}</h2><p>${t('The supplied response file contains 23 submissions collected from 25–27 June 2026. The figures below summarise overall evaluation and continuation responses; they are student-reported perceptions, not independently measured learning gains.','Fail respons yang dibekalkan mengandungi 23 penyertaan yang dikumpulkan pada 25–27 Jun 2026. Angka di bawah merumuskan penilaian keseluruhan dan cadangan penerusan; angka ini ialah persepsi kendiri pelajar, bukan peningkatan pembelajaran yang diukur secara bebas.')}</p></div><div class="xr-impact-stats"><article><strong>23</strong><span>${t('responses reviewed','respons disemak')}</span></article><article><strong>21</strong><span>${t('rated the project 5/5','menilai projek 5/5')}</span></article><article><strong>2</strong><span>${t('rated the project 4/5','menilai projek 4/5')}</span></article><article><strong>23/23</strong><span>${t('recommended continuation','mencadangkan penerusan')}</span></article></div><div class="impact-lens-grid">${impactLenses.map(([n,h,p])=>`<article><span>${n}</span><h3>${h}</h3><p>${p}</p></article>`).join('')}</div><div class="xr-evidence-actions">${button('https://docs.google.com/spreadsheets/d/1XgNDoC1_UWHAZLNw4NVhCx9H-HCTVc7O/edit?usp=drivesdk&ouid=114072147696190551583&rtpof=true&sd=true','Inspect reflection responses','Semak respons refleksi',true)}${button('https://drive.google.com/file/d/1otA0wmZ6qYSsj3HOPsm-CrLmA8M44Fr1/view?usp=drivesdk','View reflection instrument','Lihat instrumen refleksi')}${button('https://drive.google.com/file/d/11bEgxKQF7fUGAlbY0pr19r2c1RewyXxf/view?usp=drivesdk','View reflection poster','Lihat poster refleksi')}</div><p class="source-note">${t('Names and registration numbers from the raw response file are not reproduced on this website.','Nama dan nombor pendaftaran daripada fail respons mentah tidak dipaparkan semula di laman web ini.')}</p></section>

  <details class="xr-detail gallery-detail"><summary>${t('View real implementation and first-draft presentation galleries','Lihat galeri pelaksanaan sebenar dan pembentangan draf pertama')}</summary><div><p>${t('These photographs document the physical learning environment, student operation, peer review and first-draft presentation. They are supporting implementation evidence rather than measured impact.','Foto ini mendokumenkan persekitaran pembelajaran fizikal, pengendalian oleh pelajar, semakan rakan dan pembentangan draf pertama. Foto ini ialah bukti pelaksanaan sokongan dan bukan impak yang diukur.')}</p>${draftPresentationGallery()}${implementationGallery()}</div></details>

  <details class="xr-detail decision-detail"><summary>${t('Open the interactive design decision log','Buka log keputusan reka bentuk interaktif')}</summary><div><p>${t('This browser-local worksheet helps visitors examine the reasoning process without competing with the core evidence above. Nothing is submitted to a lecturer or database.','Lembaran kerja setempat dalam pelayar ini membantu pengunjung meneliti proses penaakulan tanpa mengganggu bukti utama di atas. Tiada maklumat dihantar kepada pensyarah atau pangkalan data.')}</p><section class="worksheet">${fields.map(([id,en,bm])=>`<label for="note-${id}">${t(en,bm)}</label><textarea id="note-${id}" data-note="${id}">${esc(state.notes[id]||'')}</textarea>`).join('')}<div class="actions"><button class="button primary" data-export>${t('Download decision log','Muat turun log keputusan')} ↓</button><button class="button" data-print>${t('Print / Save PDF','Cetak / Simpan PDF')}</button></div><p id="save-status" class="source-note"></p></section></div></details>

  <section class="xr-repositories"><div><span class="label">${t('COMPLETE EVIDENCE REPOSITORIES','REPOSITORI BUKTI LENGKAP')}</span><h2>${t('Follow the evidence trail.','Ikuti jejak bukti.')}</h2><p>${t('These folders retain the larger project files, portfolio samples and reflection records. The website presents selected evidence; the repositories support deeper inspection.','Folder ini menyimpan fail projek yang lebih besar, sampel portfolio dan rekod refleksi. Laman web memaparkan bukti terpilih; repositori menyokong semakan yang lebih mendalam.')}</p></div><div class="repository-actions">${button('https://drive.google.com/drive/folders/1dvK2s0vCPsF1QePG0BCWRXwmjfVz6Lli?usp=sharing','Projects & e-portfolios','Projek & e-portfolio',true)}${button('https://drive.google.com/drive/folders/1GiY7A5pPk2AwPUgg4aKsVTv2gp8KhwCO?usp=sharing','Reflection & impact evidence','Bukti refleksi & impak')}</div></section>${bridge('The implementation evidence now leads to the next question: how should access, documentation and future evaluation be strengthened?','Bukti pelaksanaan ini membawa kepada persoalan seterusnya: bagaimana akses, dokumentasi dan penilaian masa hadapan boleh diperkukuh?','#resources')}`;
}
const renderers={overview,why,model,challenge:challengeEnhanced,evidence:evidenceEnhanced,sustain,resources};
function route(){const key=location.hash.slice(1);return pages.some(p=>p[0]===key)?key:'overview';}
function render(focus=false){const key=route(),idx=pages.findIndex(p=>p[0]===key);document.documentElement.lang=state.lang==='bm'?'ms':'en';document.title='ARCHI-SPACE | '+t(pages[idx][1],pages[idx][2]);document.querySelector('.edition').textContent=t('ORIGINS • DISCOVERY • DEVELOPMENT','ASAL USUL • PENEMUAN • PEMBANGUNAN');document.querySelector('.brand small').textContent=t('ARCHITECTURAL LEARNING','PEMBELAJARAN SENI BINA');document.querySelectorAll('[data-lang]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.lang===state.lang));document.getElementById('navigation').innerHTML=pages.map(([id,en,bm],i)=>`<a href="#${id}" ${id===key?'aria-current="page"':''}><span>0${i+1}</span>${t(en,bm)}</a>`).join('');document.getElementById('content').innerHTML=renderers[key]()+`<div class="page-nav">${idx?button('#'+pages[idx-1][0],'← Back','← Kembali'): '<span></span>'}<p>${t('SECTION','BAHAGIAN')} ${idx+1} / ${pages.length}</p>${idx<6?button('#'+pages[idx+1][0],t(pages[idx+1][1],pages[idx+1][2]),t(pages[idx+1][1],pages[idx+1][2]),true):button('#overview','Back to overview','Kembali ke pengenalan')}</div>`;document.getElementById('footer').innerHTML=`<div><strong>ARCHI—SPACE</strong><br>${t('Build. Experience. Evaluate. Improve.','Bina. Alami. Nilai. Tambah baik.')}</div><div>${t('ARCHI-SPACE · Development story','ARCHI-SPACE · Perjalanan pembangunan')}<br>${t('Concept, implementation and evidence are labelled separately.','Konsep, pelaksanaan dan bukti dilabel secara berasingan.')}</div><a href="#resources">${t('Resources & development','Sumber & pembangunan')} ↗</a>`;updateCheck();if(focus){document.getElementById('content').focus({preventScroll:true});window.scrollTo({top:0,behavior:'instant'});}}
function notify(msg){const el=document.getElementById('status');el.textContent=msg;el.classList.add('show');setTimeout(()=>el.classList.remove('show'),2600);}
function updateCheck(){const el=document.getElementById('check-total');if(el)el.textContent=`${Object.values(state.checks).filter(Boolean).length}/7 ${t('preparation items marked','item persediaan ditanda')}`;}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.lang){state.lang=b.dataset.lang;save();render();}if(b.dataset.openStage!==undefined){stage=Number(b.dataset.openStage);location.hash='model';}if(b.dataset.stage!==undefined){stage=Number(b.dataset.stage);document.querySelectorAll('[data-stage]').forEach(x=>x.setAttribute('aria-pressed',Number(x.dataset.stage)===stage));document.getElementById('stage-detail').innerHTML=stageContent();}if(b.dataset.compare){const original=b.dataset.compare==='base';document.querySelectorAll('[data-compare]').forEach(x=>x.setAttribute('aria-pressed',x===b));const im=document.getElementById('compare-image');im.src=original?'assets/base-model.jpg':'assets/design-options.jpg';im.alt=original?t('Original SeVRa model','Model asal SeVRa'):t('SeVRa selected design direction','Hala tuju reka bentuk SeVRa dipilih');document.getElementById('compare-caption').textContent=original?t('Original model · approximately 1:34 in the supplied video.','Model asal · sekitar 1:34 dalam video.'):t('Selected design direction · approximately 1:59. This is a visual proposal, not verified performance evidence.','Hala tuju dipilih · sekitar 1:59. Ini cadangan visual, bukan bukti prestasi yang disahkan.');}if(b.dataset.filter){filter=b.dataset.filter;document.querySelectorAll('[data-filter]').forEach(x=>x.setAttribute('aria-pressed',x===b));document.querySelectorAll('[data-category]').forEach(x=>x.hidden=filter!=='all'&&filter!==x.dataset.category);}if(b.hasAttribute('data-print'))window.print();if(b.hasAttribute('data-export')){const body=['ARCHI-SPACE — '+t('Design decision log','Log keputusan reka bentuk'),t('Proposed learning activity; participant notes, not verified results.','Cadangan aktiviti pembelajaran; catatan peserta, bukan hasil yang disahkan.'),'',...fields.flatMap(([id,en,bm])=>[t(en,bm),state.notes[id]||t('[Not completed]','[Belum diisi]'),''])].join('\n');const url=URL.createObjectURL(new Blob([body],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='archi-space-decision-log.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notify(t('Decision log downloaded','Log keputusan dimuat turun'));}});
document.addEventListener('input',e=>{const el=e.target;if(el.dataset.note){state.notes[el.dataset.note]=el.value;const ok=save();document.getElementById('save-status').textContent=ok?t('Saved on this browser.','Disimpan dalam pelayar ini.'):t('Browser storage unavailable. Download your work before leaving.','Storan pelayar tidak tersedia. Muat turun kerja sebelum keluar.');}});
document.addEventListener('change',e=>{if(e.target.dataset.check!==undefined){state.checks[e.target.dataset.check]=e.target.checked;save();updateCheck();}});
window.addEventListener('hashchange',()=>render(true));render();
